const rtdal008744Source0001 = `.spatOpts <- function() terra:::spatOptions("", FALSE, list())`

const rtdal008744Source0002 = `f1 <- function(x, w, m, fillvalue, narm, naonly, naomit, fun, expand) {
	r <- x
	r@pntr <- x@pntr$focal(w, m, fillvalue, narm, naonly, naomit, fun, expand, .spatOpts())
	as.vector(values(r))
}`

const rtdal008744Source0003 = `f2 <- function(x, w, m, fillvalue, narm, naonly, naomit, fun, expand) {
	r <- x
	r@pntr <- x@pntr$focal2(w, m, fillvalue, narm, naonly, naomit, fun, expand, .spatOpts())
	as.vector(values(r))
}`

const rtdal008744Source0004 = `cmp <- function(x, w, m, fun, ..., fillvalue=NA, narm=FALSE, naonly=FALSE, naomit=FALSE, expand=FALSE) {
	a <- f1(x, w, m, fillvalue, narm, naonly, naomit, fun, expand)
	b <- f2(x, w, m, fillvalue, narm, naonly, naomit, fun, expand)
	expect_equal(a, b, info=paste("fun=", fun, "narm=", narm, "expand=", expand, ...))
}`

