const rtdal008794Source0064 = `setMethod("modal", signature("SpatRaster"),
	function(x, ..., ties="first", na.rm=FALSE, filename="", overwrite=FALSE, wopt=list()) {
		opt <- spatOptions(filename, overwrite, wopt=wopt)
		dots <- list(...)
		add <- NULL
		if (length(dots) > 0) {
			cls <- sapply(dots, function(i) inherits(i, "SpatRaster"))
			if (any(cls)) {
				y <- c(dots[cls], x)
				x <- do.call(c, y)
			}
			if (!all(cls)) {
				dots <- dots[!cls]
				i <- sapply(dots, function(x) class(x) %in% c("logical", "integer", "numeric"))
				add <- unlist(dots[i], use.names = FALSE)
			}
		}

		if (is.null(add)) {
			add <- c(.5)[0]
		}
		x@pntr <- x@pntr$modal(add, ties[1], na.rm[1], opt)
		messages(x, "modal")
	}
)`

const rtdal008794Source0065 = `setMethod("compare", signature(x="SpatRaster"),
    function(x, y, oper, falseNA=FALSE, filename="", overwrite=FALSE, ...){
		if (!is.character(oper)) {
			error("compare", "oper must be a character value")
		}
		oper = oper[1]
		ops <- c("==", "!=", ">", "<", ">=", "<=")
		if (!(oper %in% ops)) {
			error("compare", "oper must be a one of", ops)		
		}

		opt <- spatOptions(filename, overwrite, ...)
		if (inherits(y, "SpatRaster")) {
			x@pntr <- x@pntr$arith_rast(y@pntr, oper, falseNA[1], opt)
		} else {
			x@pntr <- x@pntr$arith_numb(y, oper, FALSE, falseNA[1], opt)
		}
		messages(x, oper)
	}
)`

const rtdal008794Source0066 = `setMethod("logic", signature(x="SpatRaster"),
    function(x, oper, falseNA=FALSE, filename="", overwrite=FALSE, ...){
		if (!is.character(oper)) {
			error("logic", "oper must be a character value")
		}
		oper = oper[1]
		opt <- spatOptions(filename, overwrite, ...)
		falseNA <- as.logical(falseNA[1])
		
		if (oper == "is.infinite") {
			x@pntr <- x@pntr$is_wrapper("isinfinite", falseNA, opt)
		} else if (oper == "is.finite") {
			x@pntr <- x@pntr$is_wrapper("isfinite", falseNA, opt)
		} else if ((oper == "is.na") | (oper == "isNA")) {
			x@pntr <- x@pntr$is_wrapper("isnan", falseNA, opt)
		} else if (oper == "not.na") {
			x@pntr <- x@pntr$is_wrapper("isnotnan", falseNA, opt)
		} else if (oper == "isTRUE") {
			x@pntr <- x@pntr$is_wrapper("is_true", falseNA, opt)
		} else if (oper == "isFALSE") {
			x@pntr <- x@pntr$is_wrapper("is_false", falseNA, opt)
		} else if (oper == "allNA") {
			x@pntr <- x@pntr$is_wrapper("allnan", falseNA, opt)
		} else if (oper == "anyNA") {
			x@pntr <- x@pntr$is_wrapper("anynan", falseNA, opt)
		} else if ((oper == "noNA") | (oper == "noneNA")) {
			x@pntr <- x@pntr$is_wrapper("nonan", falseNA, opt)
		} else if (oper == "!") {
			x@pntr <- x@pntr$arith_numb(0, "==", FALSE, falseNA[1], opt)
		} else {
			ops <- c("!", "is.na", "not.na", "allNA", "anyNA", "noneNA", "is.infinite", "is.finite", "isTRUE", "isFALSE")
			error("compare", "oper must be a one of", ops)		
		}
		messages(x, "logic")
	}
)`

