const rtdal008805Source0015 = `setMethod("crs<-", signature("SpatRaster", "ANY"),
	function(x, warn=FALSE, value) {
		if (missing(value)) {
			value <- warn
			warn <- FALSE
		}
		value <- .txtCRS(value)
		if (warn && (crs(x) != "") && (value != "")) {
			message(crs_msg)
		}
		x@pntr <- x@pntr$deepcopy()
		x@pntr$set_crs(value)
		messages(x, "crs<-")
	}
)`

