const rtdal008805Source0023 = `setMethod("is.lonlat", signature("SpatRaster"),
	function(x, perhaps=FALSE, warn=TRUE, global=FALSE) {
		if (perhaps) {
			ok <- x@pntr$isLonLat()
			if (ok) {
				if (warn) {
					messages(x, "is.lonlat")
				} else {
					 w <- x@pntr$getWarnings()
				}
				if (global) {
					return(x@pntr$isGlobalLonLat())
				} else {
					return(ok)
				}
			} 
			ok <- x@pntr$couldBeLonLat()
			if (ok) {
				if (warn) {
					messages(x, "is.lonlat")
				} else {
					x@pntr$getWarnings()
				}
				if (global) {
					ok <- x@pntr$isGlobalLonLat()
				}
			}
			if (ok && warn) {
				warn("is.lonlat", "assuming lon/lat crs")
			}
		} else {
			ok <- x@pntr$isLonLat()
			if (ok) {
				if (warn) {	
					messages(x, "is.lonlat")
				} else {
					x@pntr$getWarnings()
				}
				if (global) {
					ok <- x@pntr$isGlobalLonLat()
				}
			} else if (crs(x) == "") {
				ok <- NA
				warn("is.lonlat", "unknown crs")
			}
		}
		ok
	}
)`

