	// R| 		x@pntr$empty
	// R| 	}
	// R| )
	_ = runtime.MustCall(ctx, "setMethod", runtime.PrimitiveArg(runtime.CharacterScalar("is.empty")), runtime.PrimitiveArg(runtime.MustCall(ctx, "signature", runtime.NamedPrimitiveArg("x", runtime.CharacterScalar("SpatExtent")))), runtime.PrimitiveArg(runtime.NewNativeFunction(ctx.Global, []runtime.NativeParameter{{Name: "x"}}, func(ctx *runtime.Context, env *runtime.Environment) (runtime.Value, error) {
		return runtime.MustCallIn(ctx, env, "$", runtime.PrimitiveArg(runtime.MustCallIn(ctx, env, "@", runtime.PrimitiveArg(runtime.MustLookup(ctx, env, "x")), runtime.PrimitiveArg(runtime.CharacterScalar("pntr")))), runtime.PrimitiveArg(runtime.CharacterScalar("empty"))), nil
	})))
