const rtdal008813Source0002 = ".extract_spatraster <- function(x, i, drop) {\n\n\tif (!hasValues(i)) {\n\t\terror(\"`[`\", \"the index SpatRaster must have values\")\n\t}\n\n\tif (nlyr(i) > 1) {\n\t\terror(\"`[`\", \"the index SpatRaster can only have one layer\")\n\t}\n\n\tif (!compareGeom(x, i, crs=FALSE, stopOnError=FALSE)) {\n\t\tif (!drop) {\n\t\t\treturn(crop(x, i))\n\t\t}\n\t\ti <- cells(x, ext(i))\n\t\treturn (x[i, drop=drop])\n\t}\n\tif (drop) {\n\t\ti <- which(values(i)==1)\n\t\tvalues(x)[i, ,drop=FALSE]\n\t} else {\n\t\tif (is.bool(i)) {\n\t\t\tmask(x, i, maskvalues=FALSE)\n\t\t} else {\n\t\t\tmask(x, i)\n\t\t}\n\t}\n}"

const rtdal008813Source0003 = `.extract_spatextent <- function(x, i, drop) {
	x <- crop(x, i)
	if (drop) {
		values(x)
	} else {
		x
	}
}`

const rtdal008813Source0004 = `.extract_spatvector <- function(x, i, drop) {
	if (drop) {
		extract(x, i, data.frame=TRUE)[ , -1, drop=FALSE]
	} else {
		crop(x, i, mask=TRUE)
	}
}`

const rtdal008813Source0008 = `.extract_cell <- function(x, i, drop=TRUE, raw=FALSE) {
	if (!drop) {
		rc <- rowColFromCell(x, i)
		e <- ext_from_rc(x, min(rc[,1]), max(rc[,1]), min(rc[,2]), max(rc[,2]))
		y <- crop(x, e)
		y[-cellFromXY(y, xyFromCell(x, i))] <- NA
		y
	} else {
		opt <- spatOptions()
		e <- x@pntr$extractCell(i-1, opt)
		x <- messages(x, "extract")
		e <- do.call(cbind, e)
		colnames(e) <- names(x)
		if (raw) {
			return(e)
		}
		.makeDataFrame(x, e)
	}
}`

const rtdal008813Source0009 = `.extract_cell_layer <- function(x, i, lyrs, drop) {
	if (drop) {
		opt <- spatOptions()
		e <- x@pntr$extractCell(i-1, opt)
		messages(x, "extract")
		e <- do.call(cbind, e)
		colnames(e) <- names(x)
		e <- .makeDataFrame(x, e)
		e[cbind(1:length(i), lyrs)]
	} else {
		rc <- rowColFromCell(x, i)
		e <- ext_from_rc(x, min(rc[,1]), max(rc[,1]), min(rc[,2]), max(rc[,2]))
		x <- x[unique(lyrs)]
		crop(x, e)
	}
}`

const rtdal008813Source0010 = "setMethod(\"[\", c(\"SpatRaster\", \"ANY\", \"ANY\", \"ANY\"),\n\tfunction(x, i, j, k, drop=TRUE) {\n\n\t\tm <- c(missing(i), missing(j), missing(k))\n\t\tif (!m[3]) {\n\t\t\tif (is.logical(k) && length(k) == 1) {\n\t\t\t\tdrop <- k\n\t\t\t\tm[3] <- TRUE\n\t\t\t}\n\t\t}\n\n\t\ts <- rep(FALSE, 3)\n\t\tif (!m[1]) s[1] <- is.list(i)\n\t\tif (!m[2]) s[2] <- is.list(j)\n\t\tif (!m[3]) s[3] <- is.list(k)\n\n\t\tif (any(s)) {\n\t\t\tif (m[1]) i <- NULL \n\t\t\tif (m[2]) j <- NULL \n\t\t\tif (m[3]) k <- NULL \n\t\t\tm <- c(FALSE, TRUE, TRUE)\n\t\t\ti <- rcl(x, row=i, col=j, lyr=k)\n\t\t}\n\n\n\t\tif ((!m[1]) && (inherits(i, \"matrix\"))) {\n\t\t\tif (ncol(i) == 1) {\n\t\t\t\ti <- i[,1]\n\t\t\t} else if (ncol(i) == 2) {\n\t\t\t\ti <- cellFromRowCol(x, i[,1], i[,2])\n\t\t\t\tm[2:3] <- TRUE\n\t\t\t} else if (ncol(i) == 3) {\n\t\t\t\tk <- i[,3]\n\t\t\t\ti <- cellFromRowCol(x, i[,1], i[,2])\n\t\t\t\tuk <- unique(k)\n\t\t\t\tif (length(uk) == 1) {\n\t\t\t\t\tx <- x[[uk]]\n\t\t\t\t\tm[2:3] <- TRUE\n\t\t\t\t} else {\n\t\t\t\t\treturn(.extract_cell_layer(x, i, k, drop))\n\t\t\t\t}\n\t\t\t} else {\n\t\t\t\terror(\"`[<-`\", paste(\"index i has\", ncol(i), \"columns\"))\n\t\t\t}\n\t\t} \n\n\t\tif (!m[3]) {\n\t\t\tif (is.logical(k) && length(k) == 1) {\n\t\t\t\tdrop <- k\n\t\t\t\tm[3] <- TRUE\n\t\t\t} else {\n\t\t\t\tif (inherits(k, \"character\")) {\n\t\t\t\t\tk <- match(k, names(x))\n\t\t\t\t\tif (any(is.na(k))) {\n\t\t\t\t\t\terror(\"`[`(k)\", \"invalid layer name(s)\")\n\t\t\t\t\t}\n\t\t\t\t} else {\n\t\t\t\t\tk <- make_extract_index(k, nlyr(x), \"k\")\n\t\t\t\t}\n\t\t\t\tx <- x[[k]]\n\t\t\t}\n\t\t}\n\t\tif ((!m[1]) && (inherits(i, \"character\"))) {\n\t\t\t# partial matching of layer names\n\t\t\ti <- grep(i, names(x))\n\t\t\tx <- subset(x, i, NSE=FALSE)\n\t\t\tif (m[2]) return(x)\n\t\t\tm[1] <- TRUE\n\t\t}\n\n\n\t\tif (m[1] && m[2]) {\n\t\t\tif (drop) {\n\t\t\t\treturn(values(x, mat=TRUE))\n\t\t\t} else {\n\t\t\t\treturn(deepcopy(x))\n\t\t\t}\n\t\t} \n\n\t\tif (!m[1]) { # i not missing\n\t\t\tif (inherits(i, \"SpatRaster\")) {\n\t\t\t\treturn(.extract_spatraster(x, i, drop))\n\t\t\t} \n\t\t\tif (inherits(i, \"SpatVector\")) {\n\t\t\t\treturn(.extract_spatvector(x, i, drop))\n\t\t\t}\n\t\t\tif (inherits(i, \"SpatVector\")) {\n\t\t\t\treturn(.extract_spatextent(x, i, drop))\n\t\t\t}\n\n\t\t\ttheCall <- sys.call(-1)\n\t\t\tnarg <- length(theCall)-length(match.call(call=theCall))\n\t\t\tif ((narg==0) && m[2]) {\n\t\t\t\t# cell\n\t\t\t\ti <- make_extract_index(i, ncell(x), \"i\")\n\t\t\t\treturn(.extract_cell(x, i, drop=drop))\n\t\t\t} else if (m[2]) {\n\t\t\t\t# row\n\t\t\t\ti <- make_extract_index(i, nrow(x), \"i\")\n\t\t\t\treturn(.extract_row(x, i, drop=drop))\n\t\t\t} else {\n\t\t\t\t#row,col\n\t\t\t\ti <- make_extract_index(i, nrow(x), \"i\")\n\t\t\t\tj <- make_extract_index(j, ncol(x), \"j\")\n\t\t\t\treturn(.extract_rowcol(x, i, j, drop=drop))\n\t\t\t}\n\t\t} else { #if (!m[2]) {\n\t\t\t#col\n\t\t\tj <- make_extract_index(j, ncol(x), \"j\")\n\t\t\treturn(.extract_col(x, j, drop=drop))\n\t\t}\n\t} \n)"

