const rtdal008814Source0002 = `.focal_chunk_apply <- function(chunk, .ufun, .dots) {
	if (length(.dots)) {
		do.call(apply, c(list(chunk, 1L, .ufun), .dots))
	} else {
		apply(chunk, 1L, .ufun)
	}
}`

const rtdal008814Source0003 = `.focal_combine <- function(parts, transp) {
	if (length(parts) == 1L) return(parts[[1L]])
	first <- parts[[1L]]
	if (is.matrix(first)) {
		# fun returns vector / matrix per cell -> apply gives matrix with cells along columns
		do.call(cbind, parts)
	} else {
		# fun returns scalar per cell -> each chunk is a vector
		unlist(parts, use.names = FALSE)
	}
}`

const rtdal008814Source0004 = "setMethod(\"focal\", signature(x=\"SpatRaster\"),\nfunction(x, w=3, fun=\"sum\", ..., na.policy=\"all\", fillvalue=NA, expand=FALSE, silent=TRUE, cores=1, cpkgs=NULL, filename=\"\", overwrite=FALSE, wopt=list())  {\n\n\tdots <- list(...)\n\tif (is.null(dots$new)) {\n\t\tnew <- TRUE\n\t} else {\n\t\tnew <- isTRUE(dots$new)\n\t}\n\n\t#if (!is.null(dots$na.only)) {\n\t#\twarn(\"focal\", \"use 'na.policy' instead of 'na.only'\")\n\t#\tna.policy <- \"only\"\n\t#}\n\tna.policy <- match.arg(tolower(na.policy), c(\"all\", \"only\", \"omit\"))\n\tna.only <- na.policy == \"only\"\n\tna.omit <- na.policy == \"omit\"\n\n\tif (!is.numeric(w)) {\n\t\terror(\"focal\", \"w should be numeric vector or matrix\")\n\t}\n\ttxtfun <- .makeTextFun(fun)\n\n\tif (is.matrix(w)) {\n\t\tm <- as.vector(t(w))\n\t\t#if (!all(m %in% c(0, 1, NA))) {\n\t\t\t#if (isTRUE(list(...)$na.rm)) {\n\t\t\t#\tif (txtfun != \"sum\") {\n\t\t\t\t\t# error(\"focal\", 'with \"na.rm=TRUE\" and weights other than 0, 1, or NA, only fun=\"sum\" is allowed')\n\t\t\t#\t}\n\t\t\t#}\n\t\t#}\n\t\tw <- dim(w)\n\t} else {\n\t\tw <- rep_len(w, 2)\n\t\tstopifnot(all(w > 0))\n\t\tm <- rep(1, prod(w))\n\t}\n\tcpp <- FALSE\n\n\tif (is.character(txtfun)) {\n\t\tif (is.null(wopt$names)) {\n\t\t\twopt$names <- paste0(\"focal_\", txtfun)\n\t\t}\n\t\topt <- spatOptions(filename, overwrite, wopt=wopt)\n\t\tif (na.only) {\n\t\t\tnarm <- TRUE\n\t\t} else {\n\t\t\tnarm <- isTRUE(dots$na.rm)\n\t\t}\n\t\tif (new) {\n\t\t\tx@pntr <- x@pntr$focal2(w, m, fillvalue, narm, na.only, na.omit, txtfun, expand, opt)\n\t\t} else {\n\t\t\tx@pntr <- x@pntr$focal(w, m, fillvalue, narm, na.only, na.omit, txtfun, expand, opt)\n\t\t}\n\t\tmessages(x, \"focal\")\n\t\treturn(x)\n\n\t} else {\n\t\tif (expand) {\n\t\t\twarn(\"focal\", \"expand is ignored for functions that are not 'built-in'\")\n\t\t}\n\t\tcheckNA <- na.only || na.omit\n\n\t\tmsz <- prod(w)\n\t\tdow <- !isTRUE(all(m == 1))\n\t\tif (any(is.na(m))) {\n\t\t\tk <- !is.na(m)\n\t\t\tmm <- m[k]\n\t\t\tmsz <- sum(k)\n\t\t}\n\n\t\tv <- focalValues(x, w, trunc(nrow(x)/2), 1)[ncol(x)/2, ,drop=FALSE]\n\t\tif (dow) {\n\t\t\tif (any(is.na(m))) {\n\t\t\t\tv <- v[,k,drop=FALSE] * mm\n\t\t\t} else {\n\t\t\t\tv <- v * m\n\t\t\t}\n\t\t}\n\t\ttest <- try(apply(v, 1, fun, ...), silent=silent)\n\t\tif (inherits(test, \"try-error\")) {\n\t\t\terror(\"focal\", \"test failed\")\n\t\t}\n\n\t\t# Resolve the `cores` argument. For the R-fun path we parallelise the\n\t\t# per-block apply() across local processes (PSOCK or future). The\n\t\t# C++/built-in path is already TBB-parallel and ignores `cores`.\n\t\t# `.is_future_plan` / `.tile_apply_dispatch` come from tile_apply.R.\n\t\tif (.is_future_plan(cores)) {\n\t\t\tif (!requireNamespace(\"future\", quietly=TRUE) ||\n\t\t\t\t!requireNamespace(\"future.apply\", quietly=TRUE)) {\n\t\t\t\terror(\"focal\", \"a future plan was passed but 'future' and 'future.apply' are not installed\")\n\t\t\t}\n\t\t\toplan <- future::plan(cores)\n\t\t\ton.exit(future::plan(oplan), add=TRUE)\n\t\t\tcores <- \"future\"\n\t\t}\n\t\tdisp <- .tile_apply_dispatch(cores)\n\t\tncores <- disp$ncores\n\t\tpar_kind <- disp$kind\n\t\tcl <- disp$cl\n\t\towns_cl <- disp$owns_cl\n\n\t\tif (par_kind == \"cluster\" && is.null(cl)) {\n\t\t\tif (!requireNamespace(\"parallel\", quietly=TRUE)) {\n\t\t\t\terror(\"focal\", \"'parallel' package is required for cores>1\")\n\t\t\t}\n\t\t\tcl <- parallel::makeCluster(ncores)\n\t\t\towns_cl <- TRUE\n\t\t\t# load any extra packages on workers (the user fun may need them).\n\t\t\t# `terra` itself is not needed -- workers only see numeric matrices.\n\t\t\tif (length(cpkgs)) {\n\t\t\t\tok <- parallel::clusterCall(cl, function(pkgs) {\n\t\t\t\t\tfor (p in pkgs) suppressPackageStartupMessages(\n\t\t\t\t\t\tlibrary(p, character.only = TRUE))\n\t\t\t\t\tTRUE\n\t\t\t\t}, as.character(cpkgs))\n\t\t\t}\n\t\t}\n\t\tif (owns_cl) {\n\t\t\ton.exit({\n\t\t\t\ttry(parallel::stopCluster(cl), silent=TRUE)\n\t\t\t}, add=TRUE)\n\t\t}\n\n\t\treadStart(x)\n\t\ton.exit(readStop(x), add=TRUE)\n\t\tnl <- nlyr(x)\n\t\toutnl <- nl * length(test)\n\t\tout <- rast(x, nlyr=outnl)\n\n\t\ttransp <- FALSE\n\t\tnms <- NULL\n\t\tif (isTRUE(nrow(test) > 1)) {\n\t\t\ttransp <- TRUE\n\t\t\tnms <- rownames(test)\n\t\t\tif (nl > 1) {\n\t\t\t\tnms <- paste0(rep(names(x), each=nl), \"_\", rep(nms, nl))\n\t\t\t}\n\t\t} else if (isTRUE(ncol(test) > 1)) {\n\t\t\tnms <- colnames(test)\n\t\t\tif (nl > 1) {\n\t\t\t\tnms <- paste0(rep(names(x), each=nl), \"_\", rep(nms, nl))\n\t\t\t}\n\t\t} else {\n\t\t\tnms <- names(x)\n\t\t\tif (nl > 1) {\n\t\t\t\tnms <- paste0(rep(names(x), each=nl), \"_\", rep(1:length(test), nl))\n\t\t\t}\n\t\t}\n\t\tif (length(nms) == nlyr(out)) {\n\t\t\tnames(out) <- nms\n\t\t}\n\t\tb <- writeStart(out, filename, overwrite, n=msz+2, sources=sources(x), wopt=wopt)\n\t\topt <- spatOptions()\n\n\t\t# Threshold below which falling back to single-process apply() is faster\n\t\t# than splitting & shipping chunks to workers.\n\t\tmin_rows_for_par <- max(256L, 64L * ncores)\n\n\t\tfor (i in 1:b$n) {\n\t\t\tvv <- NULL\n\t\t\tfor (j in 1:nl) {\n\t\t\t\tif (nl > 1) {\n\t\t\t\t\tv <- x[[j]]@pntr$focalValues(w, fillvalue, b$row[i]-1, b$nrows[i], opt)\n\t\t\t\t} else {\n\t\t\t\t\tv <- x@pntr$focalValues(w, fillvalue, b$row[i]-1, b$nrows[i], opt)\n\t\t\t\t}\n\t\t\t\tif (dow) {\n\t\t\t\t\tif (any(is.na(m))) {\n\t\t\t\t\t\tv <- v[k] * mm\n\t\t\t\t\t} else {\n\t\t\t\t\t\tv <- v * m\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tv <- matrix(v, ncol=msz, byrow=TRUE)\n\n\t\t\t\tif (par_kind != \"seq\" && nrow(v) >= min_rows_for_par) {\n\t\t\t\t\tchunks <- .focal_split_chunks(v, ncores)\n\t\t\t\t\tif (par_kind == \"cluster\") {\n\t\t\t\t\t\tparts <- parallel::parLapplyLB(cl, chunks,\n\t\t\t\t\t\t\t.focal_chunk_apply, .ufun=fun, .dots=dots)\n\t\t\t\t\t} else {  # future\n\t\t\t\t\t\tparts <- future.apply::future_lapply(chunks,\n\t\t\t\t\t\t\t.focal_chunk_apply, .ufun=fun, .dots=dots, future.seed=TRUE)\n\t\t\t\t\t}\n\t\t\t\t\tv <- .focal_combine(parts, transp)\n\t\t\t\t} else {\n\t\t\t\t\tv <- apply(v, 1, fun, ...)\n\t\t\t\t}\n\t\t\t\tif (transp) {\n\t\t\t\t\tv <- t(v)\n\t\t\t\t}\n\n\t\t\t\tif (checkNA) {\n\t\t\t\t\tif (nl > 1) {\n\t\t\t\t\t\tmv <- readValues(x[[j]], b$row[i], b$nrows[i])\n\t\t\t\t\t} else {\n\t\t\t\t\t\tmv <- readValues(x, b$row[i], b$nrows[i])\n\t\t\t\t\t}\n\t\t\t\t\t\n\t\t\t\t\tif (na.only) {\n\t\t\t\t\t\tk <- !is.na(mv)\n\t\t\t\t\t} else {\n\t\t\t\t\t\tk <- is.na(mv)\n\t\t\t\t\t}\n\t\t\t\t\tv[k] <- mv[k]\n\t\t\t\t}\n\t\t\t\tif (nl > 1) {\n\t\t\t\t\tif (outnl > 1) {\n\t\t\t\t\t\tvv <- cbind(vv, v)\n\t\t\t\t\t} else {\n\t\t\t\t\t\tvv <- c(vv, v)\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (nl > 1) {\n\t\t\t\twriteValues(out, vv, b$row[i], b$nrows[i])\n\t\t\t} else {\n\t\t\t\twriteValues(out, v, b$row[i], b$nrows[i])\n\t\t\t}\n\t\t}\n\t\tout <- writeStop(out)\n\t\treturn(out)\n\t}\n}\n)"

const rtdal008814Source0005 = `setMethod("focal3D", signature(x="SpatRaster"),
function(x, w=3, fun=mean, ..., na.policy="all", fillvalue=NA, pad=FALSE, padvalue=fillvalue, expand=FALSE, silent=TRUE, filename="", overwrite=FALSE, wopt=list()) {


	na.policy <- match.arg(tolower(na.policy), c("all", "only", "omit"))
	na.only <- na.policy == "only"
	na.omit <- na.policy == "omit"
	checkNA <- na.only || na.omit

	if (!(inherits(w, "numeric") || inherits(w, "array"))) {
		error("focal3D", "w should be numeric vector or array")
	}

	if (is.array(w)) {
		if (length(dim(w)) != 3) {
			error("focal3D", "the weights array must have three dimensions")
		}
		m <- as.vector(w)
		w <- dim(w)
	} else {
		w <- rep_len(w, 3)
		stopifnot(all(w > 0))
		m <- rep(1, prod(w))
	}

	if (w[3] > nlyr(x)) {
		error("focal3D", "the third weights dimension is larger than nlyr(x)")
	}
	if (any((w[1:2] %% 2) == 0)) {
		error("focal3D", "w must be odd sized in the first two dimensions")
	}

	msz <- prod(w)
	dow <- !isTRUE(all(m == 1))
	rna <- FALSE
	if (any(is.na(m))) {
		rna <- TRUE
		kna <- !is.na(m)
		m <- m[kna]
		msz <- sum(kna)
	}

	opt <- spatOptions()
	halfway <- floor(w[3]/2)
	v <- lapply(1:w[3], function(i) focalValues(x[[i]], w[1:2], trunc(nrow(x)/2), 1)[ncol(x)/2, ,drop=FALSE])
	v <- t(do.call(cbind, v))
	if (dow) {
		if (rna) {
			v <- v[kna,,drop=FALSE] * m
		} else {
			v <- v * m
		}
	}
	vout <- try(apply(v, 2, fun, ...), silent=silent)
	if (inherits(vout, "try-error")) {
		error("focal", "test failed")
	}

	readStart(x)
	on.exit(readStop(x))
	nl <- nlyr(x)
	transp <- FALSE
	nms <- NULL
	if (isTRUE(nrow(vout) > 1)) {
		transp <- TRUE
		nms <- rownames(vout)
	} else if (isTRUE(ncol(vout) > 1)) {
		nms <- colnames(vout)
	}

	if (pad || expand) {
		startlyr = 1;
		endlyr = nl;
		outnl <- nl * length(vout)
	} else {
		startlyr = halfway+1;
		endlyr = nl-halfway;
		outnl <- (1+endlyr-startlyr) * length(vout)
	}

	out <- rast(x, nlyr=outnl)
	if (!is.null(nms)) {
		if (length(nms) <= outnl) {
			names(out) <- rep_len(nms, outnl) 
		}
	}
	b <- writeStart(out, filename, overwrite, n=msz+2, sources=sources(x), wopt=wopt)

	nread <- prod(w[1:2])

	for (i in 1:b$n) {
		nc <- b$nrows[i]*ncol(x)
		vv <- NULL
		if (expand) {
			v <- list(matrix(x[[1]]@pntr$focalValues(w, fillvalue, b$row[i]-1, b$nrows[i], opt), ncol=nc))
			v <- do.call(rbind, rep(v, halfway+1))
			for (k in 2:(1+halfway)) {
				v <- rbind(v,  matrix(x[[k]]@pntr$focalValues(w, fillvalue, b$row[i]-1, b$nrows[i], opt), ncol=nc))
			}
		} else if (pad) {
			v <- matrix(padvalue, ncol=b$nrows[i]*ncol(x), nrow=nread*halfway)
			for (k in 1:(1+halfway)) {
				v <- rbind(v,  matrix(x[[k]]@pntr$focalValues(w, fillvalue, b$row[i]-1, b$nrows[i], opt), ncol=nc))
			}
		} else {
			v <- lapply(1:w[3],
				function(k) {
					y <- x[[k]]
					z <- y@pntr$focalValues(w, fillvalue, b$row[i]-1, b$nrows[i], opt)
					y <- messages(y, "focal3D")
					matrix(z, ncol=nc)
				})
				
			v <- do.call(rbind, v)
		}
		for (j in startlyr:endlyr) {
			if (j > startlyr) {
				v <- v[-c(1:nread), ]
				k <- j + halfway
				if (k > nl) {
					if (pad) {
						v <- rbind(v, matrix(padvalue, nrow=nread, ncol=ncol(v)))
					} else {
						v <- rbind(v, v[(nrow(v)-nread):nrow(v), ])
					}
				} else {
					v <- rbind(v, matrix(x[[k]]@pntr$focalValues(w, fillvalue, b$row[i]-1, b$nrows[i], opt), ncol=ncol(v)))
				}
			}
			if (dow) {
				if (rna) {
					vout <- apply(v[kna,] * m, 2, fun, ...)
				} else {
					vout <- apply(v * m, 2, fun, ...)
				}
			} else {
				vout <- apply(v, 2, fun,...)
			}

			if (transp) {
				vout <- t(vout)
			}
			if (checkNA) {
				mv <- readValues(x[[j]], b$row[i], b$nrows[i])
				if (na.only) {
					k <- !is.na(mv)
				} else {
					k <- is.na(mv)
				}
				vout[k] <- mv[k]
			}
			vv <- c(vv, as.vector(vout))
		}
		writeValues(out, vv, b$row[i], b$nrows[i])
	}
	out <- writeStop(out)
	return(out)
}
)`

const rtdal008814Source0006 = `setMethod("focalCpp", signature(x="SpatRaster"),
function(x, w=3, fun, ..., fillvalue=NA, silent=TRUE, filename="", overwrite=FALSE, wopt=list())  {

	if (!(all(c("ni", "nw") %in% names(formals(fun))))) {
		error("focalRaw", 'fun must have an argument "ni"')
	}

	if (!is.numeric(w)) {
		error("focal", "w should be numeric vector or matrix")
	}
	if (is.matrix(w)) {
		m <- as.vector(t(w))
		w <- dim(w)
	} else {
		w <- rep_len(w, 2)
		stopifnot(all(w > 0))
		m <- rep(1, prod(w))
	}

	msz <- prod(w)
	readStart(x)
	on.exit(readStop(x))
	dow <- !isTRUE(all(m == 1))
	if (any(is.na(m))) {
		k <- !is.na(m)
		mm <- m[k]
		msz <- sum(k)
	}

	opt <- spatOptions()
	nl <- nlyr(x)
	v <- x@pntr$focalValues(w, fillvalue, max(0, trunc(nrow(x)/2)), 1, opt)[1:prod(w)]
	if (dow) {
		if (any(is.na(m))) {
			v <- v[k] * mm
		} else {
			v <- v * m
		}
	}
	test <- try(fun(v, ..., ni=1, nw=msz), silent=silent)
	if (inherits(test, "try-error")) {
		error("focalCpp", "test failed")
	}
	outnl <- nl * length(test)
	if (is.null(wopt$names )) {
		wopt$names <- colnames(test)
	}
	out <- rast(x, nlyr=outnl)
	b <- writeStart(out, filename, overwrite, n=msz*2, sources=sources(x), wopt=wopt)

	nc <- ncol(out)
	for (i in 1:b$n) {
		vv <- NULL
		for (j in 1:nl) {
			if (nl > 1) {
				v <- x[[j]]@pntr$focalValues(w, fillvalue, b$row[i]-1, b$nrows[i], opt)
			} else {
				v <- x@pntr$focalValues(w, fillvalue, b$row[i]-1, b$nrows[i], opt)
			}
			sst <- messages(x)
			if (dow) {
				if (any(is.na(m))) {
					v <- v[k] * mm
				} else {
					v <- v * m
				}
			}
			v <- fun(v, ..., ni=b$nrows[i]*nc, nw=msz)
			if (nl > 1) {
				if (outnl > 1) {
					vv <- rbind(vv, v)
				} else {
					vv <- c(vv, v)
				}
			}
		}
		if (nl > 1) {
			writeValues(out, vv, b$row[i], b$nrows[i])
		} else {
			writeValues(out, v, b$row[i], b$nrows[i])
		}
	}
	writeStop(out)
}
)`

const rtdal008814Source0007 = `.getRegFun <- function(fun, weighted=FALSE, wopt, nmsx, nl, na.rm=FALSE, intercept=TRUE, ...) {

	ols <- function(x, y, ...) {
		if (any(is.na(x)) || any(is.na(y)) || (NROW(y) < (NCOL(x) + 1))) { 
			return(rep(NA, NCOL(x)+1))
		}
		stats::.lm.fit(cbind(1, x), y)$coefficients
	}

	ols_noi <- function(x, y, ...) {
		if (any(is.na(x)) || any(is.na(y)) || (NROW(y) < (NCOL(x)))) { 
			return(rep(NA, NCOL(x)))
		}
		stats::.lm.fit(as.matrix(x), y)$coefficients
	}

	ols_narm <- function(x, y, ...) {
		v <- stats::na.omit(cbind(y, x))
		if (nrow(v) < (NCOL(x) + 1)) {
			return( cbind(rep(NA, NCOL(x)+1)) )
		}
		stats::.lm.fit(cbind(1, v[,-1]), v[,1])$coefficients
	}
	
	ols_noi_narm <- function(x, y, ...) {
		v <- stats::na.omit(cbind(y, x))
		if (nrow(v) < (NCOL(x))) {
			return( cbind(rep(NA, NCOL(x))) )
		}
		stats::.lm.fit(v[,-1,drop=FALSE], v[,1])$coefficients
	}

	weighted_ols <- function(x, y, weights, ...) {
		if (any(is.na(x)) || any(is.na(y)) || any(is.na(weights)) || (NROW(y) < (NCOL(x) + 1))) { 
			return(rep(NA, NCOL(x)+1))
		}
		stats::lm.wfit(cbind(1, x), y, weights)$coefficients		
	}

	weighted_ols_noi <- function(x, y, weights, ...) {
		if (any(is.na(x)) || any(is.na(y)) || any(is.na(weights)) || (NROW(y) < (NCOL(x) + 1))) { 
			return(rep(NA, NCOL(x)))
		}
		stats::lm.wfit(as.matrix(x), y, weights)$coefficients		
	}

	weighted_ols_narm <- function(x, y, weights, ...) {
		v <- stats::na.omit(cbind(y, weights, x))
		if (nrow(v) < (NCOL(x) + 1)) {
			return(rep(NA, NCOL(x)+1))
		}
		stats::lm.wfit(cbind(1, v[,-c(1:2)]), v[,1], v[,2])$coefficients		
	}	

	weighted_ols_noi_narm <- function(x, y, weights, ...) {
		v <- stats::na.omit(cbind(y, weights, x))
		if (nrow(v) < (NCOL(x))) {
			return(rep(NA, NCOL(x)))
		}
		stats::lm.wfit(v[,-c(1:2), drop=FALSE], v[,1], v[,2])$coefficients		
	}	


	fun <- tolower(fun[1])
	if (fun != "ols") {
		return(list(fun=fun, wopt=wopt))
	}

	intercept <- isTRUE(intercept)
	
	if (intercept) {
		if (weighted) {
			if (na.rm) {
				fun <- weighted_ols_narm
			} else {
				fun <- weighted_ols				
			}
		} else {
			if (na.rm) {
				fun = ols_narm
			} else {
				fun = ols				
			}
		}
		if (is.null(wopt$names )) {
			wopt$names <- c("intercept", nmsx[-1])
		}
	} else {
		if (weighted) {
			if (na.rm) {
				fun <- weighted_ols_noi_narm
			} else {
				fun <- weighted_ols_noi				
			}
		} else {
			if (na.rm) {
				fun = ols_noi_narm
			} else {
				fun = ols_noi				
			}
		}
		if (is.null(wopt$names )) {
			wopt$names <- nmsx[-1]
		}
		nl = nl-1
	}

	list(fun=fun, wopt=wopt, nl=nl, intercept=intercept, na.rm=na.rm)
}`

const rtdal008814Source0008 = `setMethod("focalReg", signature(x="SpatRaster"),
function(x, w=3, fun="ols", ..., fillvalue=NA, filename="", overwrite=FALSE, wopt=list()) {

	nl <- nlyr(x)
	if (nl < 2) error("focalReg", "x must have at least 2 layers")

	if (!is.numeric(w)) {
		error("focalReg", "w should be numeric vector or matrix")
	}

	weighted <- FALSE
	if (is.matrix(w)) {
		m <- as.vector(t(w))
		m[m==0] <- NA
		test <- stats::na.omit(m)
		if (length(test) == 0) {
			error("focalReg", "all values in w are NA and/or zero")
		}
		if (any(test != 1)) {
			weighted <- TRUE
			message("the focal values are used as weights")
		} 
		w <- dim(w)
	} else {
		w <- rep_len(w, 2)
		stopifnot(all(w > 0))
		m <- rep(1, prod(w))
	}

	msz <- prod(w)
	if (msz < 2) {
		error("the effective weight matrix must have positive dimensions, and at least one must be > 1")
	}

	hasnam <- FALSE
	if (any(is.na(m))) {
		hasnam <- TRUE
		k <- !is.na(m)
		msz <- sum(k)
		weights <- m[k]
	} else if (weighted) {
		weights <- m	
	}

	if (is.character(fun)) {
		funopt <- .getRegFun(fun, weighted, wopt, names(x), nlyr(x), ...) 
		fun <- funopt$fun
		wopt <- funopt$wopt
		outnl <- funopt$nl
	} else {
		# need to test
		X <- matrix(sample(msz * (nl-1), replace=TRUE), ncol=nl-1)
		if (weighted) {
			out <- fun(1:msz, X, weights=weights, ...)
		} else {
			out <- fun(1:msz, X, ...)		
		}
		outnl <- length(out)
		if (is.null(wopt$names) && (length(names(out)) == outnl)) {
			wopt$names <- names(out)
		}
	}
	out <- rast(x, nlyr=outnl)
	
	b <- writeStart(out, filename, n=msz+2, sources=sources(x), wopt=wopt)
	ry <- x[[1]]
	rx <- x[[-1]]

	if (nl == 2) {
		for (i in 1:b$n) {
			Y <- focalValues(ry, w, b$row[i], b$nrows[i], fillvalue)
			X <- focalValues(rx, w, b$row[i], b$nrows[i], fillvalue)
			if (hasnam) {
				Y <- Y[,k,drop=FALSE]
				X <- X[,k,drop=FALSE]
			}
			if (weighted) {
				v <- t(sapply(1:nrow(Y), function(i) fun(X[i,], Y[i,], weights, ...)))			
			} else {
				v <- t(sapply(1:nrow(Y), function(i) fun(X[i,], Y[i,], ...)))
			}
			writeValues(out, v, b$row[i], b$nrows[i])
		}
	} else {

		for (i in 1:b$n) {
			Y <- focalValues(ry, w, b$row[i], b$nrows[i], fillvalue)
			if (hasnam) {
				Y <- Y[,k,drop=FALSE]
			}
			X <- list()
			for (j in 1:(nl-1)) {
				X[[j]] <- focalValues(rx[[j]], w, b$row[i], b$nrows[i], fillvalue)
				if (hasnam) {
					X[[j]] <- X[[j]][,k]
				}
			}
			v <- list()
			for (p in 1:nrow(Y)) {
				xlst <- list()
				for (j in 1:(nl-1)) {
					xlst[[j]] <- X[[j]][p,]
				}
				pX <- do.call(cbind, xlst)
				if (weighted) {
					v[[p]] <- fun(pX, Y[p,], weights=weights, ...)
				} else {
					v[[p]] <- fun(pX, Y[p,], ...)
				}
			}
			v <- t(do.call(cbind, v))
			writeValues(out, v, b$row[i], b$nrows[i])
		}
	}

	out <- writeStop(out)
	return(out)
}
)`

const rtdal008814Source0009 = `setMethod("focalPairs", signature(x="SpatRaster"),
function(x, w=3, fun, ..., fillvalue=NA, filename="", overwrite=FALSE, wopt=list()) {

	pearson <- function(x, y, ...) { 
		.pearson(x, y, FALSE)
	}
	pearson_narm <- function(x, y, ...) { 
		.pearson(x, y, TRUE)
	}

	weighted_pearson <- function(x, y, weights, ...) { 
		.weighted_pearson(x, y, weights, FALSE)
	}
	weighted_pearson_narm <- function(x, y, weights, ...) { 
		.weighted_pearson(x, y, weights, TRUE)
	}
	
	nl <- nlyr(x)
	if (nl < 2) error("focalPairs", "x must have at least 2 layers")

	if (!is.numeric(w)) {
		error("focalPairs", "w should be a numeric vector or matrix")
	}
	weighted <- FALSE
	if (is.matrix(w)) {
		m <- as.vector(t(w))
		m[m==0] <- NA
		test <- stats::na.omit(m)
		if (length(test) == 0) {
			error("focalPairs", "all values in w are NA and/or zero")
		}
		if (any(test != 1)) {
			weighted <- TRUE
			message("the focal values are used as weights")
		} 
		w <- dim(w)
	} else {
		w <- rep_len(w, 2)
		stopifnot(all(w > 0))
		m <- rep(1, prod(w))
	}
	msz <- prod(w)

	hasnam <- FALSE
	if (any(is.na(m))) {
		hasnam <- TRUE
		k <- !is.na(m)
		msz <- sum(k)
		weights <- m[k]
	} else if (weighted) {
		weights <- m	
	}

	if (msz < 2) {
		error("focalPairs", "the effective weight matrix must have positive dimensions, and at least one must be > 1")
	}

	if (is.character(fun)) {
		narm <- isTRUE(list(...)$na.rm)
		fun <- tolower(fun[1])
		if (fun == "pearson") {
			if (weighted) {
				if (narm) {
					fun = weighted_pearson_narm
				} else {
					fun = weighted_pearson
				}
			} else {
				if (narm) {
					fun = pearson_narm
				} else {
					fun = pearson
				}
			}
		}
	}
	
	if (weighted) {
		test <- try(do.call(fun, list(1:prod(w), prod(w):1, weights=rep(1, prod(w)), ...)))
		if (inherits(test, "try-error")) {
			error("focalPairs", "'fun' does not work. Does it have a 'weights' argument?")
		}
	} else {
		test <- try(do.call(fun, list(1:prod(w), prod(w):1, ...)))
		if (inherits(test, "try-error")) {
			error("focalPairs", "'fun' does not work. Does it have two arguments (one for each layer)?")
		}
	}
	if (is.null(wopt$names )) {
		wopt$names <- colnames(test)
		wopt$overwrite <- overwrite
	}

	outnl <- (nlyr(x) - 1) * length(test)
	out <- rast(x, nlyr=outnl)

	b <- writeStart(out, filename, n=msz+2, sources=sources(x), wopt=wopt)

	for (i in 1:b$n) {
		v <- list()
		Y <- focalValues(x[[1]], w, b$row[i], b$nrows[i], fillvalue)
		if (hasnam) {
			Y <- Y[,k,drop=FALSE]
		}
		for (j in 2:nlyr(x)) {
			X <- Y
			Y <- focalValues(x[[j]], w, b$row[i], b$nrows[i], fillvalue)
			if (hasnam) {
				Y <- Y[,k,drop=FALSE]
			} 
			if (weighted) {
				v[[j-1]] <- t(sapply(1:nrow(Y), function(i) fun(X[i,], Y[i,], weights=weights, ...)))
			} else {
				v[[j-1]] <- t(sapply(1:nrow(Y), function(i) fun(X[i,], Y[i,], ...)))
			}
		}
		v <- do.call(cbind, v)
		writeValues(out, v, b$row[i], b$nrows[i])
	}
	out <- writeStop(out)
	return(out)
}
)`

