const rtdal008818Source0056 = `setMethod("quantile", signature(x="SpatVector"),
	function(x, probs=seq(0, 1, 0.25), ...) {
		x <- values(x)
		cls <- sapply(x, class)
		i <- cls != "character"
		if (!any(i)) error("quantile", "no numeric variables")
		x <- x[, i, drop=FALSE]
		apply(x, 2, function(i) quantile(i, probs=probs, ...))
	}
)`

const rtdal008818Source0057 = `setMethod("rectify", signature(x="SpatRaster"),
	function(x, method="bilinear", aoi=NULL, snap=TRUE, threads=FALSE, filename="", ...) {
		opt <- spatOptions(filename, threads=threads, ...)
		if (!is.null(aoi)) {
			if (inherits(aoi, "SpatExtent")) {
				aoi <- rast(aoi)
				useaoi <- 1
			} else if (inherits(aoi, "SpatRaster")) {
				aoi <- rast(aoi)
				useaoi <- 2
			} else {
				error("rectify", "ext must be a SpatExtent or SpatRaster")
			}
		} else {
			aoi <- rast()
			useaoi <- 0
		}
		snap <- as.logical(snap)
		x@pntr <- x@pntr$rectify(method, aoi@pntr, useaoi, snap, opt)
		messages(x, "rectify")
	}
)`

const rtdal008818Source0059 = `setMethod("resample", signature(x="SpatRaster", y="numeric"),
	function(x, y, method, threads=FALSE, by_util=FALSE, filename="", ...)  {

		stopifnot(all(y > 0))
		stopifnot(length(y) <= 2)
		fact <- rep_len(y, 2)
		r <- rast(x)
		res(r) <- res(r) * fact
		r <- crop(extend(r, c(0,1,0,1)), ext(x), snap="out") 
		if (!hasValues(x)) { 
			return(r)
		}	
		method <- resample_method(x, method)
		resample(x, r, method, threads=threads, by_util=by_util, filename=filename, ...)
	}
)`

const rtdal008818Source0060 = `setMethod("resample", signature(x="SpatRaster", y="SpatRaster"),
	function(x, y, method, threads=FALSE, by_util=FALSE, filename="", ...)  {

		method <- resample_method(x, method)
		xcrs = crs(x)
		ycrs = crs(y)
		if ((xcrs == "") && (ycrs != "")) {
			crs(x) <- ycrs
		}
		if ((ycrs == "") && (xcrs != "")) {
			crs(y) <- xcrs
		}
		opt <- spatOptions(filename, threads=threads, ...)

		if (by_util) {
			x@pntr <- x@pntr$warp_by_util(y@pntr, "", method, FALSE, FALSE, TRUE, "", numeric(0), -1.0, TRUE, 0, 0, opt)
		} else {
			x@pntr <- x@pntr$warp(y@pntr, "", method, FALSE, FALSE, TRUE, "", numeric(0), -1.0, TRUE, 0, 0, opt)
		}
		messages(x, "resample")
	}
)`

