const rtdal008818Source0073 = `setMethod("stretch", signature(x="SpatRaster"),
	function(x, minv=0, maxv=255, minq=0, maxq=1, smin=NA, smax=NA, histeq=FALSE, scale=1, maxcell=500000, bylayer=TRUE, filename="", ...) {
		if (histeq) {
			nms <- names(x)
			wopt <- list(...)
			if (is.null(wopt$names)) {
				wopt$names <- nms
			}

			if (bylayer) {	
				if (nlyr(x) > 1) {
					x <- lapply(1:nlyr(x), function(i) stretch(x[[i]], histeq=TRUE, scale=scale, maxcell=maxcell, bylayer=TRUE))
					x <- rast(x)
					names(x) <- nms 
					if (filename != "") {
						x <- writeRaster(x, filename=filename, ...)
					}
					return(x)
				}
				scale <- scale[1]
				if (scale == 1) {
					ecdfun <- stats::ecdf(na.omit(spatSample(x, maxcell, "regular")[,1]))
				} else {
					ecdfun <- function(y) {
						f <- stats::ecdf(na.omit(spatSample(x, maxcell, "regular")[,1]))
						f(y) * scale
					}
				}
				app(x, ecdfun, filename=filename, wopt=wopt)
			} else {
				scale <- scale[1]
				ecdfun <- stats::ecdf(na.omit(unlist(spatSample(x, maxcell, "regular"))))
				if (scale == 1) {
					app(x, ecdfun, filename=filename, wopt=wopt)
				} else {
					out <- app(x, ecdfun) * scale
					names(out) <- nms
					if (filename != "") {
						x <- writeRaster(x, filename=filename, ...)
					}
					x
				}
			}
		} else {
			opt <- spatOptions(filename, ...)
			x@pntr <- x@pntr$stretch(minv, maxv, minq, maxq, smin, smax, bylayer, maxcell, opt)
			messages(x, "stretch")
		}
	}
)`

const rtdal008818Source0074 = `setMethod("summary", signature(object="SpatRaster"),
	function(object, size=100000, warn=TRUE, ...)  {
		if (!hasValues(object)) {
			warn("summary", "SpatRaster has no values")
			return(invisible())
		}
		if (warn && (ncell(object) > size)) {
			warn("summary", "used a sample")
		}
		s <- spatSample(object, size, method="regular", warn=FALSE)
		summary(s, ...)
	}
)`

