	// R| setMethod("layerCor", signature(x="SpatRaster"),
	// R| 	function(x, fun, w, asSample=TRUE, use="everything", maxcell=Inf, ...) {
	// R|
	// R| 		ops <- c("everything", "complete.obs", "pairwise.complete.obs", "masked.complete")
	// R|
	// R| 		# backwards compatibility
	// R| 		na.rm <- list(...)$na.rm
	// R| 		if (isTRUE(na.rm) && (use == "everything")) {
	// R| 			use <- "pairwise.complete.obs"
	// R| 		}
	// R|
	// R| 		use <- match.arg(use, ops)
	// R| 		if (use != "everything") {
	// R| 			na.rm <- TRUE
	// R| 		} else {
	// R| 			na.rm <- FALSE
	// R| 		}
	// R|
	// R| 		stopifnot(is.logical(asSample) & !is.na(asSample))
	// R|
	// R| 		nl <- nlyr(x)
	// R| 		if (nl < 2) {
	// R| 			error("layerCor", "x must have at least 2 layers")
	// R| 		}
	// R|
	// R| 		if (inherits(fun, "character")) {
	// R| 			fun <- tolower(fun)
	// R| 			if (fun == "pearson") fun = "cor"
	// R| 			if (!(fun %in% c("cov", "weighted.cov", "cor"))) {
	// R| 				error("layerCor", "character function names must be one of: 'cor', 'cov', or 'weighted.cov'")
	// R| 			}
	// R| 			# backwards compatibility
	// R| 			if (fun == "weighted.cov") {
	// R| 				if (missing(w))	{
	// R| 					error("layerCor", "to compute weighted covariance a weights layer should be provided")
	// R| 				}
	// R| 				stopifnot( nlyr(w) == 1 )
	// R| 				x <- c(w, x)
	// R| 			}
	// R| 		} else {
	// R| 			FUN <- fun
	// R| 			fun <- ""
	// R| 		}
	// R|
	// R| 		if (maxcell < ncell(x)) {
	// R| 			x <- spatSample(x, size=maxcell, "regular", as.raster=TRUE)
	// R| 		}
	// R| 		n <- ncell(x)
	// R|
	// R| 		# for "cor" masking is done in cpp code
	// R| 		if ((use == "complete.obs") && (fun != "cor")) {
	// R| 			x <- mask(x, anyNA(x), maskvalue=TRUE)
	// R| 		}
	// R|
	// R| 		if (fun == "weighted.cov") {
	// R| 			w <- x[[1]]
	// R| 			x <- x[[-1]]
	// R|
	// R| 			means <- mat <- matrix(NA, nrow=nl, ncol=nl)
	// R| 			colnames(means) <- rownames(means) <- colnames(mat) <- rownames(mat) <- names(x)
	// R| 			sqrtw <- sqrt(w)
	// R| 			for(i in 1:nl) {
	// R| 				for(j in i:nl) {
	// R| 					s <- c(x[[c(i,j)]])
	// R| 					if (use == "pairwise.complete.obs") {
	// R| 						s <- mask(c(s, w), anyNA(s), maskvalue=TRUE)
	// R| 						ww <- s[[3]]
	// R| 						s <- s[[1:2]]
	// R| 						sumw <- unlist(global(ww, fun="sum", na.rm=TRUE) )
	// R| 						avg <- unlist(global(s * ww, fun="sum", na.rm=TRUE)) / sumw
	// R| 					} else {
	// R| 						sumw <- unlist(global(w, fun="sum", na.rm=na.rm) )
	// R| 						avg <- unlist(global(s * w, fun="sum", na.rm=na.rm)) / sumw
	// R| 					}
	// R| 					sumw <- sumw - asSample
	// R| 					s <- prod( (s - avg) * sqrtw )
	// R| 					v <- unlist(global(s, fun="sum", na.rm=na.rm)) / sumw
	// R| 					mat[j,i] <- mat[i,j] <- v
	// R| 					means[i,j] <- avg[1]
	// R| 					means[j,i] <- avg[2]
	// R| 				}
	// R| 			}
	// R| 			return( list(weighted_covariance=mat, weighted_mean=means) )
	// R| 		} else if (fun == "cov") {
	// R| 			means <- mat <- nn <- matrix(NA, nrow=nl, ncol=nl)
	// R| 			colnames(means) <- rownames(means) <- colnames(mat) <- rownames(mat) <- names(x)
	// R| 			n_ij <- n
	// R| 			for(i in 1:nl) {
	// R| 				for(j in i:nl) {
	// R| 					s <- x[[c(i,j)]]
	// R| 					if (use == "pairwise.complete.obs") {
	// R| 						m <- anyNA(s)
	// R| 						s <- mask(s, m, maskvalue=TRUE)
	// R| 						n_ij <- n - global(m, fun="sum")$sum
	// R| 					}
	// R| 					avg <- unlist(global(s, fun="mean", na.rm=na.rm) )
	// R| 					r <- prod(s - avg)
	// R| 					v <- unlist(global(r, fun="sum", na.rm=na.rm)) / (n_ij - asSample)
	// R| 					mat[j,i] <- mat[i,j] <- v
	// R| 					means[i,j] <- avg[1]
	// R| 					means[j,i] <- avg[2]
	// R| 					nn[i,j] <- nn[j,i] <- n_ij
	// R| 				}
	// R| 			}
	// R|
	// R| 			return( list(covariance=mat, mean=means, n=nn) )
	// R|
	// R| 		} else if (fun == "cor") {
	// R| 			if (isTRUE(list(...)$old)) {
	// R| 				old_pearson(x, asSample=asSample, na.rm=na.rm, nl=nl, n=n, mat=mat)
	// R| 			} else {
	// R| 				opt <- spatOptions()
	// R| 				m <- x@pntr$layerCor("cor", use, asSample, opt)
	// R| 				x <- messages(x)
	// R| 				m <- lapply(m, function(i) {
	// R| 					matrix(i, nrow=nl, byrow=TRUE, dimnames=list(names(x), names(x)))
	// R| 				})
	// R| 				names(m) <- c("correlation", "mean", "n")
	// R| 				return(m)
	// R| 			}
	// R| 		} else {
	// R| 			v <- spatSample(x, size=maxcell, "regular", na.rm=na.rm, warn=FALSE)
	// R| 			if (use %in% c("complete.obs", "complete.masked")) {
	// R| 				v <- na.omit(v)
	// R| 			}
	// R| 			mat <- matrix(NA, nrow=nl, ncol=nl)
	// R| 			for(i in 1:nl) {
	// R| 				for(j in i:nl) {
	// R| 					if (use == "pairwise.complete.obs") {
	// R| 						vij <- na.omit(v[,c(i,j)])
	// R| 						mat[j,i] <- mat[i,j] <- FUN(vij[,1], vij[,2], ...)
	// R| 					} else {
	// R| 						mat[j,i] <- mat[i,j] <- FUN(v[,i], v[,j], ...)
	// R| 					}
	// R| 				}
	// R| 			}
	// R| 			mat
	// R| 		}
	// R| 	}
	// R| )
	if _, err := runtime.RunSourceInContext(ctx, rtdal008831Source0001); err != nil {
		panic(fmt.Errorf("R block 1: %w", err))
	}

	// r2go: matrix lowering unavailable for block 2/2; original R follows.
	// R| old_pearson <- function(x, asSample, na.rm, nl, n, mat) {
	// R| 	if (na.rm) {
	// R| 		means <- matrix(NA, nrow=2, ncol=nlyr(x))
