	// R| 				means[2,i] <- mns[1]
	// R| 				means[1,j] <- mns[2]
	// R| 				sds <- unlist(global(xx, fun="sd", na.rm=na.rm) )
	// R| 				r <- prod(xx - mns)
	// R| 				nas <- unlist(global(is.na(r), fun="sum"))
	// R| 				v <- unlist(global(r, fun="sum", na.rm=na.rm))
	// R| 				v <- v / ((n - nas - asSample) * sds[1] * sds[2])
	// R| 				mat[j,i] <- mat[i,j] <- v
	// R| 			}
	// R| 		}
	// R| 		colnames(means) <- names(x)
