const rtdal008832Source0001 = `setMethod("droplevels", signature(x="SpatRaster"),
	function(x, level=NULL, layer=1) {
		if (is.null(level)) {
			x@pntr <- x@pntr$droplevels()
			messages(x)
		} else {
			if (is.character(layer)) {
				layer <- match(layer, names(x))
				if (any(is.na(layer))) {
					error("droplevels", "invalid layer")
				}
			}
			x[[layer]][x[[layer]] %in%  level] <- NA
			x@pntr <- x@pntr$droplevels()
			messages(x)
		}
	}
)`

const rtdal008832Source0002 = `setMethod("simplifyLevels", signature(x="SpatRaster"),
	function(x, filename="", overwrite=FALSE, ...) {

		f <- function(r) {
			v <- levels(r)[[1]]
			s <- split(v, v[,2])
			i <- sapply(s, nrow) > 1
			if (any(i)) {
				s <- s[i]
				s <- lapply(s, function(i) cbind(i[-1,1], i[1,1])) 
				s <- do.call(rbind, s)
			}	
			y <- classify(x, s)
			v <- v[-s[,1], ]
			levels(y) <- v
			y
		}
		out <- rast(lapply(x, f))
		if (filename != "") {
			out <- writeRaster(out, filename, overwrite=overwrite, ...)
		}	
		out
	}
)`

