const rtdal008835Source0001 = `getCatIDs <- function(x, table, sender="%in%") {
	if (!is.factor(x)) {
		error(sender, "Can only match character values if x is categorical")
	}
	if (nlyr(x) != 1) {
		error(sender, "cannot match with multiple layers --- this should not happen, please report")
	}
	d <- cats(x)[[1]]
	m <- stats::na.omit(match(table, d[,2]))
	d[m,1]
}`

const rtdal008835Source0003 = `setMethod("%in%", signature(x="SpatRaster"),
	function(x, table) {

		table <- unique(table)
		if (is.character(table)) {
			if (nlyr(x) > 1) {
				return(rast(lapply(x, function(i) i %in% table)))
			}
			table <- getCatIDs(x, table)
			if (length(table) == 0) {
				return(as.logical(x*0))
			}
		}
		opt <- spatOptions("", FALSE, list())
		x@pntr <- x@pntr$is_in(table, opt)
		messages(x, "%in%")
	}
)`

