const rtdal008839Source0001 = `setMethod("names", signature(x="SpatRaster"),
	function(x) {
		nms <- x@pntr$names
		Encoding(nms) <- "UTF-8"
		nms
	}
)`

const rtdal008839Source0002 = `setMethod("names<-", signature(x="SpatRaster"),
	function(x, value)  {
		if (is.null(value)) {
			value <- rep("", nlyr(x))
		} else {
			value <- enc2utf8(as.character(value))
			if (length(value) != nlyr(x)) {
				error("names<-", "incorrect number of names")
			}
		}
		x@pntr <- x@pntr$deepcopy()
		if (! x@pntr$setNames(value, FALSE)) {
			error("names<-", "cannot set these names")
		}
		return(x)
	}
)`

const rtdal008839Source0004 = `setMethod("set.names", signature(x="SpatRaster"),
	function(x, value, index=1:nlyr(x), validate=FALSE)  {
		value <- .names_check(x, value, index, validate, nlyr)
		if (!x@pntr$setNames(value, FALSE)) {
			error("set.names", "cannot set these names")
		}
		invisible(TRUE)
	}
)`

