const rtdal008881Source0026 = "setMethod(\"[\", c(\"SpatRasterCollection\", \"numeric\", \"missing\"),\nfunction(x, i, j, ... ,drop=TRUE) {\n\ti <- positive_indices(i, length(x), TRUE, \"`[`(i)\")\n\tif (drop && (length(i) == 1)) {\n\t\ttptr <- x@pntr$x[[i]]\n\t\tx <- rast()\n\t\tx@pntr <- tptr\n\t} else {\n\t\ts <- x@pntr$x[i]\n\t\ttptr <- SpatRasterCollection$new()\n\t\tfor (i in 1:length(s)) {\n\t\t\ttptr$add(s[[i]], \"\")\n\t\t}\n\t\tx@pntr <- tptr\n\t}\n\tmessages(x, \"`[`\")\n})"

