const rtdal008882Source0001 = `setMethod("geomtype", signature(x="SpatVector"),
	function(x){
		x@pntr$type()
	}
)`

const rtdal008882Source0002 = `setMethod("geomtype", signature(x="SpatVectorProxy"),
	function(x){
		x@pntr$v$type()
	}
)`

const rtdal008882Source0003 = `setMethod("datatype", signature(x="SpatVector"),
	function(x){
		x@pntr$df$get_datatypes()
	}
)`

const rtdal008882Source0007 = `setMethod("has.z", signature(x="SpatVector"),
	function(x) {
		x@pntr$has_z()
	}
)`

const rtdal008882Source0009 = `setMethod("geom", signature(x="SpatVector"),
	function(x, wkt=FALSE, hex=FALSE, wkb=FALSE, df=FALSE, list=FALSE, xnm="x", ynm="y"){
		if (hex) {
			x@pntr$hex()
		} else if (wkt) {
			x@pntr$wkt()
		} else if (list) {
			x@pntr$get_geometryList(xnm, ynm)
		} else if (wkb) {
			x@pntr$wkb_raw()
		}	else {
			g <- x@pntr$get_geometry()
			g <- do.call(cbind, g)
			colnames(g) <- c("geom", "part", "x", "y", "hole", "z")[1:ncol(g)]
			if (df) {
				data.frame(g)
			} else {
				g
			}
		}
	}
)`

const rtdal008882Source0010 = `setMethod("crds", signature(x="SpatVector"),
	function(x, df=FALSE, list=FALSE){
		if (list) {
			gt <- geomtype(x) 
			if (gt == "lines") {
				x@pntr$linesNA()
			} else if (gt == "polygons") {
				x@pntr$polygonsList()			
			} else {
				x@pntr$coordinates()
			}
		} else {
			g <- x@pntr$coordinates()
			g <- do.call(cbind, g)
			colnames(g) <- c("x", "y", "z")[1:ncol(g)]
			if (df) {
				data.frame(g)
			} else {
				g
			}
		}
	}
)`

const rtdal008882Source0011 = `setMethod("crds", signature(x="SpatRaster"),
	function(x, df=FALSE, na.rm=TRUE, na.all=FALSE){
#		crds( as.points(x, values=(hasValues(x) || (na.rm)), na.rm=na.rm, na.all=na.all), df=df)
		opt <- spatOptions()
		out <- x@pntr$crds(na.rm, na.all, opt)
		messages(x)
		if (df) {
			out <- data.frame(out)
		} else {
			out <- do.call(cbind, out)
		}
		colnames(out) <- c("x", "y")
		out
	}
)`

const rtdal008882Source0013 = `setMethod("dim", signature(x="SpatVectorProxy"),
	function(x){
		c(x@pntr$v$geom_count, x@pntr$v$ncol())
	}
)`

const rtdal008882Source0014 = `as.data.frame.SpatVector <- function(x, row.names=NULL, optional=FALSE, geom=NULL, ...) {
	d <- .getSpatDF(x@pntr$df, ...)
	# fix empty names
	colnames(d)[1:ncol(x)] <- x@pntr$names
	if (!is.null(geom)) {
		geom <- match.arg(toupper(geom), c("WKT", "HEX", "XY"))
		if (geom == "XY") {
			if (!grepl("points", geomtype(x))) {
				error("as.data.frame", 'geom="XY" is only valid for point geometries')
			}
			if (nrow(d) > 0) {
				d <- cbind(d, crds(x))
			} else {
				d <- data.frame(crds(x), ...)
			}
		} else {
			g <- geom(x, wkt=geom=="WKT", hex=geom=="HEX")
			if (nrow(d) > 0) {
				d$geometry <- g
			} else {
				d <- data.frame(geometry=g, stringsAsFactors=FALSE, ...)
			}
		}
	}
	d
}`

const rtdal008882Source0016 = `get.data.frame <- function(x) {
	v <- vect()
	v@pntr <- x@pntr$v
	d <- as.data.frame(v)
	d[0,,drop=FALSE]
}`

const rtdal008882Source0017 = `as.list.SpatVector <- function(x, geom=NULL, ...) {
	as.list(as.data.frame(x, geom=geom))
}`

const rtdal008882Source0019 = `setMethod ("expanse", "SpatVector",
	function(x, unit="m", transform=TRUE) {
		a <- x@pntr$area(unit, transform, double());
		x <- messages(x, "expanse");
		return(abs(a))
	}
)`

