const rtdal008884Source0001 = "positive_indices <- function(i, n, na.rm=TRUE, caller=\"`[`\") {\n\ti <- stats::na.omit(i)\n\tif (!is.logical(i)) {\n\t\tstopifnot(is.numeric(i))\n\t\tif (!(all(i <= 0) || all(i >= 0))) {\n\t\t\terror(caller, \"you cannot mix positive and negative indices\")\n\t\t}\n\t}\n\ti <- (1:n)[i]\n\tif (na.rm) {\n\t\ti[!is.na(i)]\n\t} else {\n\t\ti\n\t}\n}"

const rtdal008884Source0002 = `setMethod("subset", signature(x="SpatRaster"),
	function(x, subset, negate=FALSE, NSE=FALSE, filename="", overwrite=FALSE, ...) {
		if (NSE) {
			subset <- if (missing(subset)) {
				1:nlyr(x)
			} else {
				nl <- as.list(seq_along(names(x)))
				names(nl) <- nms <- names(x)
				v <- eval(substitute(subset), nl, parent.frame())
				if (!inherits(substitute(subset), "character")) {
					if (sum(nms %in% nms[v]) > length(v)) {
						warn("subset", "using a name that is not unique")
					}
				}
				v
			}
		}
		if (is.character(subset)) {
			nms <- names(x)
			if (!all(subset %in% nms)) {
				error("subset", "invalid name(s)")
			}
			if (sum(nms %in% subset) > length(subset)) {
				warn("subset", "using a name that is not unique")
			}
			subset <- unlist(lapply(subset, function(s) which(nms == s)), use.names = FALSE)
		}
		if (any(is.na(subset))) {
			error("subset", "undefined layer(s) selected")
		}
		if (negate) subset = -subset
		subset <- positive_indices(subset, nlyr(x), TRUE, "subset")
		opt <- spatOptions(filename, overwrite, ...)
		x@pntr <- x@pntr$subset(subset-1, opt)
		messages(x, "subset")
	}
)`

const rtdal008884Source0003 = `setMethod("$", "SpatRaster",
	function(x, name) {
		if ((nlyr(x) == 1) && is.factor(x)) {
			factnms <- names(cats(x)[[1]])
			i <- match(name, factnms[-1])
			if (!is.na(i)) {
				activeCat(x) <- i		
				return(x)
			}
		}
		subset(x, name, NSE=FALSE)
	}
)`

const rtdal008884Source0008 = `setMethod("subset", signature(x="SpatVector"),
	function(x, subset, select, drop=FALSE, NSE=FALSE) {
		
 		if (NSE) {
			d <- as.list(x)
			# from the subset<data.frame> method
			r <- if (missing(subset)) {
					TRUE
				} else {
					e <- substitute(subset)
					# r <- eval(e, d, parent.frame())
					# for #1600
					r <- eval(e, d, globalenv())
					if (!is.logical(r)) error("subset", "argument 'subset' must be logical")
					r & !is.na(r)
				}
			v <- if (missing(select)) {
					TRUE
				} else {
					nl <- as.list(seq_along(d))
					names(nl) <- names(d)
					# eval(substitute(select), nl, parent.frame())
					eval(substitute(select), nl, globalenv())
				}
			x <- x[r, v, drop=drop]
		} else {
			if (missing(subset)) subset <- TRUE
			spatcls <- isTRUE(substr(class(subset)[1], 1, 4) == "Spat")
			if (spatcls) {
				x <- x[subset]
				if (!missing(select)) {
					x <- x[, select, drop=drop]
				}
			} else if (missing(select)) {
				x <- x[(as.vector(subset)), drop=drop]
			} else {
				x <- x[(as.vector(subset)), select, drop=drop]
			}
		}
		#g <- gc()
		x
	}
)`

const rtdal008884Source0009 = `.subset_cols <- function(x, subset, drop=FALSE) {
	if (is.character(subset)) {
		i <- stats::na.omit(match(subset, names(x)))
		if (length(i)==0) {
			error("subset", "no valid variable name found")
		} else if (length(i) < length(subset)) {
			warn("subset", "invalid variable name(s) excluded")
		}
	} else {
		i <- positive_indices(subset, ncol(x), TRUE, "subset")
		if (length(i)==0) {
			i <- 0
		}
	}
	x@pntr <- x@pntr$subset_cols(i-1)
	x <- messages(x, "subset")
	if (drop) {	# drop geometry
		.getSpatDF(x@pntr$df)
	} else {
		x
	}
}`

