const rtdal008889Source0001 = `setMethod("makeTiles", signature(x="SpatRaster"),
	function(x, y, filename="tile_.tif", extend=FALSE, na.rm=FALSE, buffer=0, value="files", overwrite=FALSE, ...) {
	
		value <- match.arg(value, c("files", "raster", "collection"))
		filename <- trimws(filename[1])
		filename <- filename[!is.na(filename)]
		if (filename == "") error("makeTiles", "filename cannot be empty")
		opt <- spatOptions(filename="", overwrite=overwrite, ...)
		if (inherits(y, "SpatRaster")) {
			ff <- x@pntr$make_tiles(y@pntr, extend[1], buffer, na.rm[1], filename, opt)
		} else if (inherits(y, "SpatVector")) {
			ff <- x@pntr$make_tiles_vect(y@pntr, extend[1], buffer, na.rm[1], filename, opt)
		} else if (is.numeric(y)) {
			if (length(y) > 2) {
				error("makeTiles", "expected one or two numbers")
			}
			y <- rep_len(y, 2)
			y <- aggregate(rast(x), y)
			ff <- x@pntr$make_tiles(y@pntr, extend[1], buffer, na.rm[1], filename, opt)
		} else {
			error("makeTiles", "y must be numeric or a SpatRaster or SpatVector")
		}
		messages(x, "makeTiles")
		if (value == "files") {
			ff
		} else if (value == "raster") {
			filename <- gsub("_\\.", "s.", filename)
			vrt(ff, filename=filename)
		} else {
			sprc(ff)
		}
	}
)`

const rtdal008889Source0002 = ".auto_tile_size <- function(x, cores=1, memfrac=NULL,\n\t\t\t\t\t\t\ttasks_per_worker=4, ncopies=4) {\n\n\tnr <- nrow(x); nc <- ncol(x); nl <- nlyr(x)\n\tcores <- max(as.integer(cores)[1], 1L)\n\ttasks_per_worker <- max(as.integer(tasks_per_worker)[1], 1L)\n\n\t# block size from GDAL (per source). Use the smallest reported per dim,\n\t# then fall back to 256 when nothing useful is reported (e.g. for\n\t# in-memory rasters or sources that report 0).\n\tfb <- tryCatch(fileBlocksize(x), error=function(e) NULL)\n\tif (is.null(fb) || NROW(fb) == 0) {\n\t\tbr <- bc <- 0L\n\t} else {\n\t\tbr <- as.integer(min(fb[, \"rows\"]))\n\t\tbc <- as.integer(min(fb[, \"cols\"]))\n\t}\n\tif (is.na(br) || br <= 0) br <- min(256L, nr)\n\tif (is.na(bc) || bc <= 0) bc <- min(256L, nc)\n\tbr <- min(br, nr); bc <- min(bc, nc)\n\tone_block <- as.numeric(br) * bc\n\n\t# memory budget (bytes per cell assumes double precision and `ncopies`\n\t# in-flight copies, the same accounting blocks() and writeStart() use).\n\tbytes_per_cell <- 8 * max(nl, 1L) * max(ncopies, 1L)\n\n\tif (is.null(memfrac)) {\n\t\tmemfrac <- tryCatch(spatOptions()$memfrac, error=function(e) 0.5)\n\t\tif (is.null(memfrac) || !is.finite(memfrac) || memfrac <= 0) {\n\t\t\tmemfrac <- 0.5\n\t\t}\n\t}\n\n\tfree_kb <- tryCatch(free_RAM(), error=function(e) NA_real_)\n\tif (is.na(free_kb) || !is.finite(free_kb) || free_kb <= 0) {\n\t\t# no memory info: only the parallelism constraint applies\n\t\tmem_cells <- Inf\n\t} else {\n\t\tfree_b <- free_kb * 1024              # free_RAM returns kB\n\t\tbudget <- (free_b * memfrac) / cores  # per-worker peak budget\n\t\tmem_cells <- budget / bytes_per_cell\n\t}\n\n\t# at least one tile per worker, and ideally a few for load balancing.\n\t# Avoid integer overflow on large rasters by going through `numeric`.\n\ttotal_cells <- as.numeric(nr) * nc\n\ttarget_min_tiles <- cores * tasks_per_worker\n\tpar_cells <- total_cells / target_min_tiles\n\n\tcells_per_tile <- min(mem_cells, par_cells)\n\t# never go below a single block (avoids dicing tiled COGs into sub-blocks)\n\tcells_per_tile <- max(cells_per_tile, one_block)\n\t# never go above the whole raster\n\tcells_per_tile <- min(cells_per_tile, total_cells)\n\n\t# pick (rows, cols) as integer multiples of (br, bc), as square as possible\n\tside <- sqrt(cells_per_tile)\n\tnbr <- max(round(side / br), 1)\n\tnbc <- max(round(side / bc), 1)\n\ttile_rows <- min(as.integer(nbr * br), nr)\n\ttile_cols <- min(as.integer(nbc * bc), nc)\n\n\tc(tile_rows, tile_cols)\n}"

const rtdal008889Source0003 = `setMethod("getTileExtents", signature(x="SpatRaster"),
	function(x, y, extend=FALSE, buffer=0, cores=1) {

		if (missing(y) || is.null(y)) {
			y <- .auto_tile_size(x, cores=cores)
		}

		opt <- spatOptions(filename="")
		if (inherits(y, "SpatRaster")) {
			e <- x@pntr$get_tiles_ext(y@pntr, extend[1], buffer)
		} else if (inherits(y, "SpatVector")) {
			e <- x@pntr$get_tiles_ext_vect(y@pntr, extend[1], buffer)
		} else if (is.numeric(y)) {
			if (length(y) > 2) {
				error("getTileExtents", "expected one or two numbers")
			}
			y <- rep_len(y, 2)
			y <- aggregate(rast(x), y)
			e <- x@pntr$get_tiles_ext(y@pntr, extend[1], buffer)
		} else {
			error("getTileExtents", "y must be numeric or a SpatRaster or SpatVector")
		}
		messages(x, "getTileExtents")
		e <- matrix(e, ncol=4, byrow=FALSE)
		colnames(e) <- c("xmin", "xmax", "ymin", "ymax")
		e
	}
)`

const rtdal008889Source0004 = `setMethod("vrt", signature(x="character"),
	function(x, filename="", options=NULL, overwrite=FALSE, set_names=FALSE, return_filename=FALSE) {
		opt <- spatOptions(filename, overwrite=overwrite)
		r <- rast()
		if (is.null(options)) {
			options=""[0]
		}
		f <- r@pntr$make_vrt(x, options, opt)
		messages(r, "vrt")
		messages(opt, "vrt")
		if (set_names) {
			v <- readLines(f)
			if ("-separate" %in% options) {
			    nms <- unlist(lapply(sprc(x), names))
			} else {
			    nms <- names(rast(x[1]))
			}
			i <- grep("band=", v)
			if (length(i) == length(nms)) {
				nms <- paste0("<Description>", nms, "</Description>")
				v[i] <- paste(v[i], nms)
				writeLines(v, f)
			}
		}
		if (return_filename) {
			f
		} else {
			rast(f)
		}
	}
)`

const rtdal008889Source0005 = `setMethod("vrt", signature(x="SpatRasterCollection"),
	function(x, filename="", options=NULL, overwrite=FALSE, return_filename=FALSE) {
		opt <- spatOptions(filename, overwrite=overwrite)
		if (is.null(options)) {
			options=""[0]
		}
		f <- x@pntr$make_vrt(options, FALSE, opt)
		messages(x, "vrt")
		if (return_filename) {
			f
		} else {
			rast(f)
		}
	}
)`

