const rtdal008892Source0025 = `setMethod("compareGeom", signature(x="SpatVector", y="SpatVector"),
	function(x, y, tolerance=0) {
		out <- x@pntr$equals_between(y@pntr, tolerance)
		x <- messages(x, "compareGeom")
		out[out == 2] <- NA
		matrix(as.logical(out), nrow=nrow(x), byrow=TRUE)
	}
)`

const rtdal008892Source0026 = `setMethod("compareGeom", signature(x="SpatVector", y="missing"),
	function(x, y, tolerance=0) {
		symmetrical=FALSE # this is inefficient
		out <- x@pntr$equals_within(symmetrical, tolerance)
		x <- messages(x, "compareGeom")
		out[out == 2] <- NA
		out <- matrix(as.logical(out), nrow=nrow(x), byrow=TRUE)
		out
	}
)`

const rtdal008892Source0027 = `setMethod("all.equal", signature(target="SpatRaster", current="SpatRaster"),
	function(target, current, maxcell=100000, ...) {
		a <- base::all.equal(rast(target), rast(current))
		maxcell <- round(maxcell)
		if (isTRUE(a) && maxcell > 0) {
			hvT <- hasValues(target)
			hvC <- hasValues(current)
			if (hvT && hvC) {
				if (maxcell < ncell(target)) {
					warn(paste("all.equal", "taking a sample of ", maxcell, "cells"))
					s1 <- spatSample(current, maxcell, "regular")
					s2 <- spatSample(target, maxcell, "regular")
				} else {
					s1 <- values(current)
					s2 <- values(target)
				}
				a <- all.equal(s1, s2, ...)
			} else if (hvT || hvC) {
				if (hvT) {
					a <- "target has cell values, current does not"
				} else {
					a <- "current has cell values, target does not"				
				}
			}
		}
		a
	}
)`

const rtdal008892Source0028 = `setMethod("all.equal", signature(target="SpatExtent", current="SpatExtent"),
	function(target, current, ...) {
		target == current
	}
)`

const rtdal008892Source0029 = `setMethod("all.equal", signature(target="SpatVector", current="SpatVector"),
	function(target, current, ...) {
		if (any(dim(target) != dim(current))) {
			message("different dimensions")
			return(FALSE)
		}
		if (crs(target) != crs(current)) {
			message("different crs")
			return(FALSE)
		}
		if (geomtype(target) != geomtype(current)) {
			message("different geometry type")
			return(FALSE)
		}
		if (!isTRUE(all.equal(values(target), values(current), ...))) {
			message("different values")
			return(FALSE)
		}
		if (!isTRUE(all.equal(geom(target), geom(current), ...))) {
			message("different geometry")
			return(FALSE)
		}
		TRUE
	}
)`

const rtdal008892Source0033 = `setMethod("values", signature("SpatVector"),
	function(x, ...) {
		as.data.frame(x, ...)
	}
)`

const rtdal008892Source0034 = `setMethod("values<-", signature("SpatVector", "data.frame"),
	function(x, value) {
		x@pntr <- x@pntr$deepcopy()
		if (ncol(value) == 0) {
			x@pntr$remove_df()
			return(x)
		}
		value <- .makeSpatDF(value)
		x@pntr$set_df(value)
		messages(x)
	}
)`

const rtdal008892Source0037 = `setMethod("values<-", signature("SpatVector", "NULL"),
	function(x, value) {
		x@pntr <- x@pntr$deepcopy()
		x@pntr$remove_df()
		x
	}
)`

