const rtdal008893Source0021 = "setReplaceMethod(\"[[\", c(\"SpatVector\", \"character\"),\n\tfunction(x, i, value) {\n\n\t\tx@pntr <- x@pntr$deepcopy()\n\t\tif (is.null(value)) {\n\t\t\tfor (name in i) {\n\t\t\t\tif (name %in% names(x)) {\n\t\t\t\t\tx@pntr$remove_column(name)\n\t\t\t\t}\n\t\t\t}\n\t\t\treturn(x);\n\t\t} else if (length(value) == 0) {\n\t\t\tif (nrow(x) == 0) {\n\t\t\t\td <- values(x)\n\t\t\t\tfor (name in i) {\n\t\t\t\t\td[[name]] <- value\n\t\t\t\t}\n\t\t\t\tvalues(x) <- d\n\t\t\t\treturn(x)\n\t\t\t} else {\n\t\t\t\tvalues(x) <- NA\n\t\t\t\t#error(\"[[<-,SpatVector\", \"cannot use an empty value\")\n\t\t\t\treturn(x)\n\t\t\t}\n\t\t}\n\t\tif (inherits(value, \"data.frame\")) {\n\t\t\tif (ncol(value)\t> 1) {\n\t\t\t\twarn(\"`[[<-`\", \"only using the first column\")\n\t\t\t}\n\t\t\tvalue <- value[,1]\n\t\t} else if (inherits(value, \"list\")) {\n\t\t\tvalue <- sapply(value, function(x) if (is.null(x)) NA else x)\n\t\t}\n\n\t\tif (NCOL(value)\t> 1) {\n\t\t\twarn(\"[[<-,SpatVector\", \"only using the first column\")\n\t\t\tvalue <- value[,1]\n\t\t}\n\t\tname <- i[1]\n\n\t\tnr <- nrow(x)\n\t\tif (length(value) > nr) {\n\t\t\terror(\"$<-\", paste(\"replacement has\", length(value), \"rows, data has\", nr))\n\t\t}\n\t\tif ((nr %% length(value)) != 0) {\n\t\t\twarn(\"$<-\", \"replacement is not a multiple of the number of rows\")\n\t\t}\n\t\tvalue <- rep(value, length.out=nrow(x))\n\n\t\tif (name %in% names(x)) {\n\t\t\td <- values(x)\n\t\t\tif (all(is.na(value))) {\n\t\t\t\t#[] to keep type if NA is used\n\t\t\t\td[[name]][] <- value\n\t\t\t} else {\n\t\t\t\td[[name]] <- value\t\t\t\n\t\t\t}\n\t\t\tvalues(x) <- d\n\t\t} else {\n\t\t\tif (inherits(value, \"factor\")) {\n\t\t\t\tv <- .makeSpatFactor(value)\n\t\t\t\tok <- x@pntr$add_column_factor(v, name)\n\t\t\t} else if (inherits(value, \"character\")) {\n\t\t\t\tok <- x@pntr$add_column_string(enc2utf8(value), name)\n\t\t\t} else if (inherits(value, \"integer\")) {\n\t\t\t\t# min long (should query what it is on the system?)\n\t\t\t\tvalue[is.na(value)] <- -2147483648\n\t\t\t\tok <- x@pntr$add_column_long(value, name)\n\t\t\t} else if (inherits(value, \"logical\")) {\n\t\t\t\tv <- as.integer(value)\n\t\t\t\tv[is.na(v)] <- 2\n\t\t\t\tok <- x@pntr$add_column_bool(v, name)\n\t\t\t} else if (inherits(value, \"numeric\")) {\n\t\t\t\tok <- x@pntr$add_column_double(value, name)\n\t\t\t} else if (inherits(value, \"Date\")) {\n\t\t\t\tok <- x@pntr$add_column_time(as.numeric(as.POSIXlt(value)), name, \"days\", \"\")\n\t\t\t} else if (inherits(value, \"POSIXt\")) {\n\t\t\t\ttz <- if (length(value) > 0) { attr(value[1], \"tzone\") } else { \"\" }\n\t\t\t\tif (is.null(tz)) tz <- \"\"\n\t\t\t\tok <- x@pntr$add_column_time(as.numeric(value), name, \"seconds\", tz)\n\t\t\t} else {\n\t\t\t\tv <- try(as.character(value))\n\t\t\t\tif (!inherits(v, \"try-error\")) {\n\t\t\t\t\tok <- x@pntr$add_column_string(enc2utf8(v), name)\n\t\t\t\t} else {\n\t\t\t\t\tok <- FALSE\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (!ok) {\n\t\t\t\terror(\"[[<-,SpatVector\", \"cannot add these values\")\n\t\t\t}\n\t\t}\n\t\tx\n\t}\n)"

const rtdal008893Source0024 = "setMethod(\"vect\", signature(x=\"data.frame\"),\n\tfunction(x, geom=NULL, crs=NULL, keepgeom=FALSE, quiet=FALSE) {\n\t\t\n\t\tguessed_geom <- FALSE; lonlat <- FALSE\n\t\tif (!is.null(geom)) {\n\t\t\tif (!all(geom %in% names(x))) {\n\t\t\t\terror(\"vect\", \"the variable name(s) in argument `geom` are not in `x`\")\n\t\t\t}\n\t\t} else {\n\t\t\tif (all(c(\"lon\", \"lat\") %in% names(x))) { \n\t\t\t\t# backwards compatibility\n\t\t\t\tgeom <- c(\"lon\", \"lat\")\n\t\t\t\t# guessed_geom <- TRUE\t\n\t\t\t} else {\n\t\t\t\tif (ncol(x) <= 2) { \n\t\t\t\t\tgeom <- names(x)\t\t\t\t\n\t\t\t\t} else {\n\t\t\t\t\tnms <- tolower(names(x))\n\t\t\t\t\tm <- rbind(\tmatch(c(\"longitude\", \"latitude\"), nms),\n                                match(c(\"decimallongitude\", \"decimallatitude\"), nms),\n\t\t\t\t\t\t\t\tmatch(c(\"long\", \"lati\"), nms),\n\t\t\t\t\t\t\t\tmatch(c(\"long\", \"lat\"), nms),\t\t\t\t\t\t\t\t\n                                match(c(\"lon\", \"lat\"), nms),\n                                match(c(\"location.lon\", \"location.lat\"), nms),\n                                match(c(\"location.long\", \"location.lat\"), nms),\n                                match(c(\"location.longitude\", \"location.latitude\"), nms),\n                                match(c(\"location_lon\", \"location_lat\"), nms),\n                                match(c(\"location_long\", \"location_lat\"), nms),\n                                match(c(\"location_longitude\", \"location_latitude\"), nms),\n                                match(c(\"location-lon\", \"location-lat\"), nms),\n                                match(c(\"location-long\", \"location-lat\"), nms),\n                                match(c(\"location-longitude\", \"location-latitude\"), nms),\n\t\t\t\t\t\t\t\tmatch(c(\"easting\", \"northing\"), nms),\n\t\t\t\t\t\t\t\tmatch(c(\"xcoord\", \"ycoord\"), nms),\n                                match(c(\"x.coord\", \"y.coord\"), nms),\n                                match(c(\"x_coord\", \"y_coord\"), nms),\n                                match(c(\"x\", \"y\"), nms))\n\t\t\t\t\ttest <- !apply(is.na(m), 1, any) \n\t\t\t\t\tif (sum(test) == 1) {\n\t\t\t\t\t\tm <- m[test, ]\n\t\t\t\t\t\tgeom <- names(x)[m]\n\t\t\t\t\t\tlonlat <- which(test) < 6\n\t\t\t\t\t} else if (sum(test) == 0) {\n\t\t\t\t\t\tlon <- which(sapply(nms, function(n) grepl(n, \"longitude\")))\n\t\t\t\t\t\tlat <- which(sapply(nms, function(n) grepl(n, \"latitude\")))\n\t\t\t\t\t\tif ((length(lon) == 0) && (length(lat) == 0)) {\n\t\t\t\t\t\t\tlon <- which(sapply(nms, function(n) grepl(n, \"lon\")))\n\t\t\t\t\t\t\tlat <- which(sapply(nms, function(n) grepl(n, \"lat\")))\n\t\t\t\t\t\t}\n\t\t\t\t\t\tif ((length(lon) == 1) && (length(lat) == 1)) {\n\t\t\t\t\t\t\tgeom <- names(x)[c(lon, lat)]\n\t\t\t\t\t\t\tlonlat <- TRUE\n\t\t\t\t\t\t} \n\t\t\t\t\t} \n\t\t\t\t\tif (is.null(geom) && (ncol(x) == 2) && all(sapply(x, is.numeric))) { \n\t\t\t\t\t\tgeom <- names(x)\n\t\t\t\t\t}\n\t\t\t\t\tguessed_geom <- TRUE\n\t\t\t\t}\n\t\t\t}\n\t\t\tif (is.null(geom)) {\n\t\t\t\terror(\"vect\", \"geom=NULL and no unique lon/lat or x/y variable name pairs detected\")\n\t\t\t}\n\t\t}\n\t\t\n\t\tguessed_crs <- FALSE\n\t\tif (is.null(crs)) {\n\t\t\tcrs <- \"\"\n\t\t\tif ((guessed_geom && lonlat) || ((!guessed_geom) && grepl(\"lon\", geom[1]) && grepl(\"lat\", geom[2]))) {\n\t\t\t\txr <- range(x[,geom[1]], na.rm=TRUE)\n\t\t\t\tyr <- range(x[,geom[2]], na.rm=TRUE)\n\t\t\t\tif ((xr[1] > -181) && (xr[2] < 361)  && (yr[1] > -90.01) && (yr[2] < 90.01)) {\n\t\t\t\t\tguessed_crs <- TRUE\n\t\t\t\t\tcrs <- \"+proj=longlat\"\n\t\t\t\t}\n\t\t\t}\n\t\t} else {\n\t\t\tcrs <- character_crs(crs, \"vect\")\n\t\t}\n\t\tif (length(geom) == 2) {\n\t\t\tgeom <- match(geom[1:2], names(x))\n\t\t\tif (inherits(x[,geom[1]], \"integer\")) {\n\t\t\t\tx[,geom[1]] <- as.numeric(x[,geom[1]])\n\t\t\t}\n\t\t\tif (inherits(x[,geom[2]], \"integer\")) {\n\t\t\t\tx[,geom[2]] <- as.numeric(x[,geom[2]])\n\t\t\t}\n\t\t\tp <- methods::new(\"SpatVector\")\n\t\t\tp@pntr <- terra:::SpatVector$new()\n\t\t\tx <- terra:::.makeSpatDF(x)\n\n\t\t\tp@pntr$setPointsDF(x, geom-1, crs, keepgeom)\n\n\t\t\tp <- messages(p, \"vect\")\n\t\t\tif (!quiet) {\n\t\t\t\tif (guessed_geom & guessed_crs) {\n\t\t\t\t\twarn(\"vect\", \"guessed geom variables and crs\")\n\t\t\t\t} else if (guessed_geom) {\n\t\t\t\t\twarn(\"vect\", \"guessed geom variables\")\n\t\t\t\t} else if (guessed_crs) {\n\t\t\t\t\twarn(\"vect\", \"guessed crs\")\n\t\t\t\t}\t\t\t\n\t\t\t}\n\t\t\treturn(p)\n\t\t} else if (length(geom) == 1) {\n\t\t\tv <- vect(unlist(x[,geom]), crs=crs)\n\t\t\tif (!keepgeom) {\n\t\t\t\tx[[geom]] <- NULL\n\t\t\t}\n\t\t} else {\n\t\t\terror(\"vect\", \"the length of 'geom' must be 1 or 2\")\n\t\t}\n\t\tvalues(v) <- x\n\t\tv\n\t}\n)"

const rtdal008893Source0025 = `setMethod("vect", signature(x="list"),
	function(x, type="points", crs="") {
	
		v <- methods::new("SpatVector")
		if (inherits(x[[1]], "raw")) {
			v@pntr <- SpatVector$new()
			v@pntr$addWKB(x)
		} else {
			x <- lapply(x, function(i) {
				if (inherits(i, "SpatVector")) return(i)
				vect(i, type=type)
			})
			x <- svc(x)
			v@pntr <- x@pntr$append()
		}
		if (crs != "") {
			crs(v) <- crs
		}
		messages(v, "vect")
	}
)`

const rtdal008893Source0026 = `setMethod("query", signature(x="SpatVectorProxy"),
	function(x, start=1, n=nrow(x), vars=NULL, where=NULL, extent=NULL, filter=NULL, sql=NULL, dialect="", what="") {
		f <- x@pntr$v$source
		slayer <- x@pntr$v$layer
		#1058
		layer <- paste0("\"", slayer, "\"")

		e <- x@pntr$v$read_extent
		if (is.null(extent)) {
			if (length(e) == 4) {
				extent = ext(e);
			}
		} else {
			if (length(e) == 4) {
				extent = intersect(ext(e), extent);
				if (is.null(extent)) {
					error("query", "extent does not intersect with x")
				}
			}
		}
		if (is.null(vars)) {
			vars <- "*"
		} else {
			vars <- stats::na.omit(unique(vars))
			nms <- names(x)
			if (!all(vars %in% nms)) {
				error("query", "not all vars are variable names")
			} else if (length(vars) < length(nms))  {
				vars <- paste(vars, collapse=", ")
			}
		}

		if (!is.null(sql)) {
			qy <- as.character(sql)
		
		} else {
			qy <- ""
			if (!is.null(where)) {
				qy <- paste("SELECT", vars, "FROM", layer, "WHERE", where[1])
			} else {
				qy <- paste("SELECT", vars, "FROM", layer)
			}
			nr <- nrow(x)
			start <- start-1
			if (start > 0) {
				if (n >= (nr-start)) {
					qy <- paste(qy, "OFFSET", format(start, scientific=FALSE))
				} else {
					n <- min(n, nr-start)
					qy <- paste(qy, layer, "LIMIT", n, "OFFSET", format(start, scientific=FALSE))
				}
			} else if (n < nr) {
				n <- min(n, nr)
				qy <- paste(qy, "LIMIT", n)
			}
		}
		
		if (qy != "") {
			if (x@pntr$v$read_query != "") {
				error("query", "A query was used to create 'x'; you can only subset it with extent or filter")
			}
		} else {
			layer <- slayer
		}

		p <- vect(f, layer, query=qy, extent=extent, filter=filter, crs="", FALSE, what=what, dialect=dialect)
		if (what == "attributes") {
			p <- values(p)
		}
		p
	}
)`

const rtdal008893Source0027 = `vector_layers <- function(filename, delete="", return_error=FALSE) {
	p <- SpatVector$new()
	if (any(delete != "")) {
		delete <- trimws(delete)
		ok <- p$delete_layers(filename, delete, return_error[1])
		messages(p, "vector_layers")
		invisible(ok)
	} else {
		out <- p$layer_names(filename)
		messages(p, "vector_layers")
		out
	}
}`

