const rtdal008897Source0001 = `setMethod("blocks", signature(x="SpatRaster"),
	function(x, n=4) {
		opt <- spatOptions("", FALSE, ncopies=n)
		b <- x@pntr$getBlockSizeR(opt)
		b$row <- b$row + 1
		b
	}
)`

const rtdal008897Source0002 = `setMethod("writeStart", signature(x="SpatRaster", filename="character"),
	function(x, filename="", overwrite=FALSE, n=4, sources="", ...) {
		filename <- path.expand(trimws(filename[1]))
		filename <- enc2utf8(filename)
		opt <- spatOptions(filename, overwrite, ncopies=n, ...)
		ok <- x@pntr$writeStart(opt, unique(sources))
		messages(x, "writeStart")
		b <- x@pntr$getBlockSizeWrite()
		b$row <- b$row + 1
		b
	}
)`

const rtdal008897Source0003 = `setMethod("writeStop", signature(x="SpatRaster"),
	function(x) {
		success <- x@pntr$writeStop()
		messages(x, "writeStop")
		f <- sources(x)
		if (f != "") {
			x <- rast(f)
		}
		return(x)
	}
)`

const rtdal008897Source0004 = `setMethod("writeValues", signature(x="SpatRaster", v="vector"),
	function(x, v, start, nrows) {
		success <- x@pntr$writeValues(v, start-1, nrows)
		messages(x, "writeValues")
		invisible(success)
	}
)`

const rtdal008897Source0005 = `setMethod("writeRaster", signature(x="SpatRaster", filename="character"),
function(x, filename="", overwrite=FALSE, ...) {
	filename <- trimws(filename)
	stopifnot(filename != "")
	filename <- enc2utf8(filename)

	ftp <- list(...)$filetype[1]
	fext <- tools::file_ext(filename)
	if (any(fext %in% c("nc", "cdf")) && (is.null(ftp) || isTRUE(ftp=="netCDF"))) {
		warn("writeRaster", "consider writeCDF to write ncdf files")
	} 
	#else if ((length(fext)==1) && (any(fext == "rds")) && ((is.null(ftp)) || isTRUE(ftp=="RDS"))) {
	#	if ((!overwrite) && file.exists(filename)) {
	#		error("writeRaster", "Use 'overwrite=TRUE' to overwrite an existing file")
	#	}
	#	return(saveRDS(x, filename))
	#}
	opt <- spatOptions(filename, overwrite, ...)
	x@pntr <- x@pntr$writeRaster(opt)
	x <- messages(x, "writeRaster")
	invisible(rast(filename))
}
)`

const rtdal008897Source0006 = `setMethod("update", signature(object="SpatRaster"),
	function(object, crs=FALSE, extent=FALSE, names=FALSE, cells=NULL, values=NULL, layer=0) {
		if (!is.null(cells) || !is.null(values)) {
			if (is.null(cells) || is.null(values)) {
				error("update", "provide both 'cells' and 'values'")
			}
			if (is.character(layer)) {
				layer <- match(layer, names(object))
				if (any(is.na(layer))) {
					error("update", "invalid layer name")
				}
			}
			layer <- round(layer)
			if (all(layer > 0)) {
				layers <- as.integer(layer - 1)
			} else {
				layers <- integer(0)
			}
			opt <- spatOptions()
			ok <- object@pntr$update_values(as.double(cells - 1), as.double(values), layers, opt)
			messages(object, "update")
		}
		if (crs || extent || names) {
			opt <- spatOptions()
			ok <- object@pntr$update_meta(names, crs, extent, opt)
			messages(object, "update")
		}
		invisible(object)
	}
)`

const rtdal008897Source0007 = `get_filetype <- function(filename) {  
	fn <- tolower(filename)
	ext <- tools::file_ext(fn)
	ext2 <- gsub("^[^.]*\\.(.*).*$", "\\1", fn)
	if ((ext == "shp") || (ext == "shz") || (ext == "zip" && ext2 == "shp.zip")) {
		"ESRI Shapefile"
	} else if ((ext == "") || (ext == "gpkg") || (ext == "zip" && ext2 == "gpkg.zip")) {
		"GPKG"
	} else if (ext == "gdb") {
		"OpenFileGDB"
	} else if (ext == "gml") {
		"GML"
	} else if ((ext == "json") || (ext == "geojson")) {
		"GeoJSON"
	} else if (ext == "cdf") {
		"netCDF"
	} else if (ext == "svg") {
		"SVG"
	} else if (ext == "kml") {
		"KML"
	} else if (ext == "vct") {
		"Idrisi"
	} else if (ext == "rds") {
		"rds"
	} else if (ext == "tab") {
		"MapInfo File"
	} else if (ext == "gpx") {
		"GPX"
	} else {
		error("writeVector", "cannot guess filetype from filename")
	}
}`

const rtdal008897Source0008 = `setMethod("writeVector", signature(x="SpatVector", filename="character"),
function(x, filename, filetype=NULL, layer=NULL, insert=FALSE, overwrite=FALSE, options="ENCODING=UTF-8") {

	filename <- path.expand(trimws(filename[1]))
	filename <- enc2utf8(filename)
	if (filename == "") {
		error("writeVector", "provide a filename")
	}
	if (is.null(filetype)) {
		filetype <- get_filetype(filename)
		if (filetype == "rds") {
			return(saveRDS(x, filename))
		}
	}
	if (is.null(layer)) layer <- tools::file_path_sans_ext(basename(filename))
	layer <- trimws(layer)

	if (is.null(options)) { options <- ""[0] }

	if (filetype == "ESRI Shapefile") {
		nms <- names(x)
		i <- nchar(nms) > 10
		if (any(i)) {
			nms[i] <- substr(nms[i], 1, 10)
			testnms <- make.unique(nms, sep="")
			if (!all(testnms == nms)) {
				i <- which(i)
				newnms <- substr(nms[i], 1, 9)
				newnms <- make.unique(newnms, sep="")
				j <- which(nchar(newnms) == 9)
				newnms[j] <- paste0(newnms[j], "0")
				nms[i] <- newnms
			}
			x@pntr <- x@pntr$deepcopy()
			names(x) <- nms
		}
	}
	success <- x@pntr$write(filename, layer, filetype, insert[1], overwrite[1], options)
	messages(x, "writeVector")
	invisible(TRUE)
}
)`

