const rtdal008916Source0001 = `as_tibble <- function(
  x,
  ...,
  .rows = NULL,
  .name_repair = c(
    "check_unique",
    "unique",
    "universal",
    "minimal",
    "unique_quiet",
    "universal_quiet"
  ),
  rownames = pkgconfig::get_config("tibble::rownames", NULL)
) {
  UseMethod("as_tibble")
}`

const rtdal008916Source0002 = `as_tibble.data.frame <- function(
  x,
  validate = NULL,
  ...,
  .rows = NULL,
  .name_repair = c(
    "check_unique",
    "unique",
    "universal",
    "minimal",
    "unique_quiet",
    "universal_quiet"
  ),
  rownames = pkgconfig::get_config("tibble::rownames", NULL)
) {
  if (!is.null(validate)) {
    deprecate_stop(
      "2.0.0",
      "tibble::as_tibble(validate = )",
      "as_tibble(.name_repair =)"
    )
  }

  if (!identical(class(x), "data.frame") && !inherits(x, "tbl_df")) {
    x <- as.data.frame(x)
  }

  old_rownames <- raw_rownames(x)
  if (is.null(.rows)) {
    .rows <- nrow(x)
  }

  result <- lst_to_tibble(unclass(x), .rows, .name_repair)

  if (is.null(rownames)) {
    result
  } else if (is.na(rownames)) {
    attr(result, "row.names") <- old_rownames
    result
  } else {
    if (length(old_rownames) > 0 && is.na(old_rownames[1L])) {
      # if implicit rownames
      old_rownames <- seq_len(abs(old_rownames[2L]))
    }
    old_rownames <- as.character(old_rownames)
    add_column(
      result,
      !!rownames := old_rownames,
      .before = 1L,
      .name_repair = "minimal"
    )
  }
}`

const rtdal008916Source0003 = `as_tibble.list <- function(
  x,
  validate = NULL,
  ...,
  .rows = NULL,
  .name_repair = c(
    "check_unique",
    "unique",
    "universal",
    "minimal",
    "unique_quiet",
    "universal_quiet"
  )
) {
  if (!is.null(validate)) {
    deprecate_stop(
      "2.0.0",
      "tibble::as_tibble(validate = )",
      "as_tibble(.name_repair =)"
    )
  }

  lst_to_tibble(x, .rows, .name_repair, col_lengths(x))
}`

const rtdal008916Source0005 = `check_valid_cols <- function(x, pos = NULL, call = caller_env()) {
  names_x <- names2(x)

  is_xd <- which(!map_lgl(x, is_valid_col))
  if (has_length(is_xd)) {
    classes <- map_chr(x[is_xd], friendly_type_of)
    abort_column_scalar_type(names_x[is_xd], pos[is_xd], classes, call)
  }

  # 657
  x[] <- map(x, make_valid_col)
  invisible(x)
}`

const rtdal008916Source0010 = "as_tibble.matrix <- function(x, ..., validate = NULL, .name_repair = NULL) {\n  m <- matrixToDataFrame(x)\n  names <- colnames(x)\n  if (is.null(.name_repair)) {\n    if (\n      (is.null(names) || any(bad_names <- duplicated(names) | names == \"\")) &&\n        has_length(x)\n    ) {\n      deprecate_warn(\n        \"2.0.0\",\n        \"as_tibble.matrix(x = 'must have unique column names if `.name_repair` is omitted')\",\n        details = \"Using compatibility `.name_repair`.\"\n      )\n      compat_names <- paste0(\"V\", seq_along(m))\n      if (is.null(names)) {\n        names <- compat_names\n      } else {\n        names[bad_names] <- compat_names[bad_names]\n      }\n      .name_repair <- function(x) names\n    } else {\n      .name_repair <- \"check_unique\"\n    }\n    validate <- NULL\n  }\n\n  colnames(m) <- names\n  as_tibble(m, ..., validate = validate, .name_repair = .name_repair)\n}"

const rtdal008916Source0011 = `as_tibble.poly <- function(x, ...) {
  m <- matrixToDataFrame(unclass(x))
  colnames(m) <- colnames(x)
  as_tibble(m, ...)
}`

const rtdal008916Source0012 = `as_tibble.ts <- function(x, ..., .name_repair = "minimal") {
  df <- as.data.frame(x)
  if (length(dim(x)) == 2) {
    colnames(df) <- colnames(x)
  }
  as_tibble(df, ..., .name_repair = .name_repair)
}`

const rtdal008916Source0013 = "as_tibble.table <- function(\n  x,\n  `_n` = \"n\",\n  ...,\n  n = `_n`,\n  .name_repair = \"check_unique\"\n) {\n  if (!missing(`_n`)) {\n    warn(\"Please pass `n` as a named argument to `as_tibble.table()`.\")\n  }\n\n  df <- as.data.frame(x, stringsAsFactors = FALSE)\n\n  names(df) <- repaired_names(\n    c(names2(dimnames(x)), n),\n    repair_hint = TRUE,\n    .name_repair = .name_repair\n  )\n\n  # Names already repaired:\n  as_tibble(df, ..., .name_repair = \"minimal\")\n}"

const rtdal008916Source0014 = `as_tibble.NULL <- function(x, ...) {
  if (missing(x)) {
    deprecate_stop("3.0.0", "as_tibble(x = 'can\\'t be missing')")
  }

  new_tibble(list(), nrow = 0)
}`

const rtdal008916Source0015 = `as_tibble.default <- function(x, ...) {
  value <- x
  if (is_atomic(value)) {
    signal_superseded(
      "3.0.0",
      "as_tibble(x = 'can\\'t be an atomic vector')",
      "as_tibble_col()"
    )
  }
  as_tibble(as.data.frame(value, stringsAsFactors = FALSE), ...)
}`

const rtdal008916Source0016 = `as_tibble_row <- function(
  x,
  .name_repair = c(
    "check_unique",
    "unique",
    "universal",
    "minimal",
    "unique_quiet",
    "universal_quiet"
  )
) {
  if (!vec_is(x)) {
    abort_as_tibble_row_vector(x)
  }

  names <- vectbl_names2(x, .name_repair = .name_repair)

  # FIXME: Use vec_chop2() when https://github.com/r-lib/vctrs/pull/1226 is in
  if (is_bare_list(x)) {
    slices <- x
  } else {
    x <- vectbl_set_names(x, NULL)
    slices <- lapply(seq_len(vec_size(x)), vec_slice, x = x)
    names(slices) <- names
  }

  check_all_lengths_one(slices)

  new_tibble(slices, nrow = 1)
}`

const rtdal008916Source0017 = `check_all_lengths_one <- function(x, call = caller_env()) {
  sizes <- col_lengths(x)

  bad_lengths <- which(sizes != 1)
  if (!is_empty(bad_lengths)) {
    abort_as_tibble_row_size_one(
      seq_along(x)[bad_lengths],
      names2(x)[bad_lengths],
      sizes[bad_lengths],
      call
    )
  }
}`

